},

export const ZodInstanceOf: core.$constructor<ZodInstanceOf> = /*@__PURE__*/ core.$constructor(
  "ZodInstanceOf",
  (inst, def) => {
    ZodCustom.init(inst, def);
  },
  {
    properties(shape: core.$ZodShape, params?: string | core.$ZodCheckPropertiesParams) {
