  //   Object.assign(entries, values);
  // }
  // const entries: util.EnumLike = {};
  // for (const val of values) {
  //   entries[val] = val;
  // }

  return new Class({
    type: "enum",
    entries,
    ...util.normalizeParams(params),
  }) as any;
}

export const enumProcessor: Processor<schemas.$ZodEnum> = (schema, _ctx, json, _params) => {
  const def = schema._zod.def as schemas.$ZodEnumDef;
  const values = getEnumValues(def.entries);

  // an empty enum accepts nothing, same as z.never()
  if (values.length === 0) {
    json.not = {};
    return;
  }

  // Number enums can have both string and number values
  if (values.every((v) => typeof v === "number")) json.type = "number";
  if (values.every((v) => typeof v === "string")) json.type = "string";
  json.enum = values;
};

inst.exclude = (values, params) => {
  const newEntries: Record<string, any> = { ...def.entries };
  for (const value of values) {
    if (keys.has(value)) {
      delete newEntries[value];
    } else throw new Error(`Key ${value} not found in enum`);
  }
  return new ZodEnum({
    ...def,
    checks: [],
    ...util.normalizeParams(params),
    entries: newEntries,
  }) as any;
};

