def do_items(value: t.Union[t.Mapping[K, V], Undefined]) -> t.Iterator[t.Tuple[K, V]]:
    """Return an iterator over the ``(key, value)`` items of a mapping.

    ``x|items`` is the same as ``x.items()``, except if ``x`` is
    undefined an empty iterator is returned.

    This filter is useful if you expect the template to be rendered with
    an implementation of Jinja in another programming language that does
    not have a ``.items()`` method on its mapping type.

    .. code-block:: html+jinja

        <dl>
        {% for key, value in my_dict|items %}
            <dt>{{ key }}
            <dd>{{ value }}
        {% endfor %}
        </dl>

    .. versionadded:: 3.1
    """
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

def push(self, token: Token) -> None:
    """Push a token back to the stream."""
    self._pushed.append(token)

def iter_child_nodes(
    self,
    exclude: t.Optional[t.Container[str]] = None,
    only: t.Optional[t.Container[str]] = None,
) -> t.Iterator["Node"]:
    """Iterates over all direct child nodes of the node.  This iterates
    over all fields and yields the values of they are nodes.  If the value
    of a field is a list all the nodes in that list are returned.
    """
    for _, item in self.iter_fields(exclude, only):
        if isinstance(item, list):
            for n in item:
                if isinstance(n, Node):
                    yield n
        elif isinstance(item, Node):
            yield item

def find_referenced_templates(ast: nodes.Template) -> t.Iterator[t.Optional[str]]:
    """Finds all the referenced templates from the AST.  This will return an
    iterator over all the hardcoded template extensions, inclusions and
    imports.  If dynamic inheritance or inclusion is used, `None` will be
    yielded.

    >>> from jinja2 import Environment, meta
    >>> env = Environment()
    >>> ast = env.parse('{% extends "layout.html" %}{% include helper %}')
    >>> list(meta.find_referenced_templates(ast))
    ['layout.html', None]

    This function is useful for dependency tracking.  For example if you want
    to rebuild parts of the website after a layout template has changed.
    """
    template_name: t.Any

    for node in ast.find_all(_ref_types):
        template: nodes.Expr = node.template  # type: ignore

        if not isinstance(template, nodes.Const):
            # a tuple with some non consts in there
            if isinstance(template, (nodes.Tuple, nodes.List)):
                for template_name in template.items:
                    # something const, only yield the strings and ignore
                    # non-string consts that really just make no sense
                    if isinstance(template_name, nodes.Const):
                        if isinstance(template_name.value, str):
                            yield template_name.value
                    # something dynamic in there
                    else:
                        yield None
            # something dynamic we don't know about here
            else:
                yield None
            continue
        # constant is a basestring, direct template name
        if isinstance(template.value, str):
            yield template.value
        # a tuple or list (latter *should* not happen) made of consts,
        # yield the consts that are strings.  We could warn here for
        # non string values
        elif isinstance(node, nodes.Include) and isinstance(
            template.value, (tuple, list)
        ):
            for template_name in template.value:
                if isinstance(template_name, str):
                    yield template_name
        # something else we don't care about, we could warn here
        else:
            yield None

def iter_fields(
    self,
    exclude: t.Optional[t.Container[str]] = None,
    only: t.Optional[t.Container[str]] = None,
) -> t.Iterator[t.Tuple[str, t.Any]]:
    """This method iterates over all fields that are defined and yields
    ``(key, value)`` tuples.  Per default all fields are returned, but
    it's possible to limit that to some fields by providing the `only`
    parameter or to exclude some using the `exclude` parameter.  Both
    should be sets or tuples of field names.
    """
    for name in self.fields:
        if (
            (exclude is None and only is None)
            or (exclude is not None and name not in exclude)
            or (only is not None and name in only)
        ):
            try:
                yield name, getattr(self, name)
            except AttributeError:
                pass

def push_assign_tracking(self) -> None:
    """Pushes a new layer for assignment tracking."""
    self._assign_stack.append(set())

def enable_buffering(self, size: int = 5) -> None:
    """Enable buffering.  Buffer `size` items before yielding them."""
    if size <= 1:
        raise ValueError("buffer size too small")

    self.buffered = True
    self._next = partial(next, self._buffered_generator(size))

def __init__(self, gen: t.Iterator[str]) -> None:
    self._gen = gen
    self.disable_buffering()

@property
def is_up_to_date(self) -> bool:
    """If this variable is `False` there is a newer version available."""
    if self._uptodate is None:
        return True
    return self._uptodate()

def visit_TemplateData(self, node: nodes.TemplateData, frame: Frame) -> None:
    try:
        self.write(repr(node.as_const(frame.eval_ctx)))
    except nodes.Impossible:
        self.write(
            f"(Markup if context.eval_ctx.autoescape else identity)({node.data!r})"
        )

@internalcode
def __getattr__(self, name: str) -> t.Any:
    # Raise AttributeError on requests for names that appear to be unimplemented
    # dunder methods to keep Python's internal protocol probing behaviors working
    # properly in cases where another exception type could cause unexpected or
    # difficult-to-diagnose failures.
    if name[:2] == "__" and name[-2:] == "__":
        raise AttributeError(name)

    return self._fail_with_undefined_error()

def dump(
    self,
    fp: t.Union[str, t.IO[bytes]],
    encoding: t.Optional[str] = None,
    errors: t.Optional[str] = "strict",
) -> None:
    """Dump the complete stream into a file or file-like object.
    Per default strings are written, if you want to encode
    before writing specify an `encoding`.

    Example usage::

        Template('Hello {{ name }}!').stream(name='foo').dump('hello.html')
    """
    close = False

    if isinstance(fp, str):
        if encoding is None:
            encoding = "utf-8"

        real_fp: t.IO[bytes] = open(fp, "wb")
        close = True
    else:
        real_fp = fp

    try:
        if encoding is not None:
            iterable = (x.encode(encoding, errors) for x in self)  # type: ignore
        else:
            iterable = self  # type: ignore

        if hasattr(real_fp, "writelines"):
            real_fp.writelines(iterable)
        else:
            for item in iterable:
                real_fp.write(item)
    finally:
        if close:
            real_fp.close()

def test_iterable(value: t.Any) -> bool:
    """Check if it's possible to iterate over an object."""
    try:
        iter(value)
    except TypeError:
        return False

    return True

async def render_async(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This works similar to :meth:`render` but returns a coroutine
    that when awaited returns the entire rendered template string.  This
    requires the async feature to be enabled.

    Example usage::

        await template.render_async(knights='that say nih; asynchronously')
    """
    if not self.environment.is_async:
        raise RuntimeError(
            "The environment was not created with async mode enabled."
        )

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(  # type: ignore
            [n async for n in self.root_render_func(ctx)]  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

