        if need_eval_context:
            wrapper = pass_eval_context(wrapper)

        wrapper.jinja_async_variant = True  # type: ignore[attr-defined]
        return wrapper

    return decorator

@property
def current(self) -> t.Any:
    """Return the current item. Equivalent to the item that will be
    returned next time :meth:`next` is called.
    """
    return self.items[self.pos]

@async_variant(sync_do_unique)  # type: ignore
async def do_unique(
    environment: "Environment",
    value: "t.Union[t.AsyncIterable[V], t.Iterable[V]]",
    case_sensitive: bool = False,
    attribute: t.Optional[t.Union[str, int]] = None,
) -> "t.Iterator[V]":
    return sync_do_unique(
        environment, await auto_to_list(value), case_sensitive, attribute
    )

def as_const(self, eval_ctx: t.Optional[EvalContext] = None) -> t.Any:
    eval_ctx = get_eval_context(self, eval_ctx)

    if eval_ctx.volatile:
        raise Impossible()

    if self._is_filter:
        env_map = eval_ctx.environment.filters
    else:
        env_map = eval_ctx.environment.tests

    func = env_map.get(self.name)
    pass_arg = _PassArg.from_obj(func)  # type: ignore

    if func is None or pass_arg is _PassArg.context:
        raise Impossible()

    if eval_ctx.environment.is_async and (
        getattr(func, "jinja_async_variant", False) is True
        or inspect.iscoroutinefunction(func)
    ):
        raise Impossible()

    args, kwargs = args_as_const(self, eval_ctx)
    args.insert(0, self.node.as_const(eval_ctx))

    if pass_arg is _PassArg.eval_context:
        args.insert(0, eval_ctx)
    elif pass_arg is _PassArg.environment:
        args.insert(0, eval_ctx.environment)

    try:
        return func(*args, **kwargs)
    except Exception as e:
        raise Impossible() from e

@internalcode
def _get_default_module(self, ctx: t.Optional[Context] = None) -> "TemplateModule":
    """If a context is passed in, this means that the template was
    imported. Imported templates have access to the current
    template's globals by default, but they can only be accessed via
    the context during runtime.

    If there are new globals, we need to create a new module because
    the cached module is already rendered and will not have access
    to globals from the current context. This new module is not
    cached because the template can be imported elsewhere, and it
    should have access to only the current template's globals.
    """
    if self.environment.is_async:
        raise RuntimeError("Module is not available in async mode.")

    if ctx is not None:
        keys = ctx.globals_keys - self.globals.keys()

        if keys:
            return self.make_module({k: ctx.parent[k] for k in keys})

    if self._module is None:
        self._module = self.make_module()

    return self._module

async def auto_await(value: t.Union[t.Awaitable["V"], "V"]) -> "V":
    # Avoid a costly call to isawaitable
    if type(value) in _common_primitives:
        return t.cast("V", value)

    if inspect.isawaitable(value):
        return await t.cast("t.Awaitable[V]", value)

    return value

@internalcode
def __call__(self) -> str:
    if self._context.environment.is_async:
        return self._async_call()  # type: ignore

    rv = self._context.environment.concat(  # type: ignore
        self._stack[self._depth](self._context)
    )

    if self._context.eval_ctx.autoescape:
        return Markup(rv)

    return rv

@internalcode
async def _async_call(self) -> str:
    rv = self._context.environment.concat(  # type: ignore
        [x async for x in self._stack[self._depth](self._context)]  # type: ignore
    )

    if self._context.eval_ctx.autoescape:
        return Markup(rv)

    return rv

def _invoke(self, arguments: t.List[t.Any], autoescape: bool) -> str:
    if self._environment.is_async:
        return self._async_invoke(arguments, autoescape)  # type: ignore

    rv = self._func(*arguments)

    if autoescape:
        rv = Markup(rv)

    return rv

