def enable_buffering(self, size: int = 5) -> None:
    """Enable buffering.  Buffer `size` items before yielding them."""
    if size <= 1:
        raise ValueError("buffer size too small")

    self.buffered = True
    self._next = partial(next, self._buffered_generator(size))

def _buffered_generator(self, size: int) -> t.Iterator[str]:
    buf: t.List[str] = []
    c_size = 0
    push = buf.append

    while True:
        try:
            while c_size < size:
                c = next(self._gen)
                push(c)
                if c:
                    c_size += 1
        except StopIteration:
            if not c_size:
                return
        yield concat(buf)
        del buf[:]
        c_size = 0

def sync_do_list(value: "t.Iterable[V]") -> "t.List[V]":
    """Convert the value into a list.  If it was a string the returned list
    will be a list of characters.
    """
    return list(value)

def do_items(value: t.Union[t.Mapping[K, V], Undefined]) -> t.Iterator[t.Tuple[K, V]]:
    """Return an iterator over the ``(key, value)`` items of a mapping.

    ``x|items`` is the same as ``x.items()``, except if ``x`` is
    undefined an empty iterator is returned.

    This filter is useful if you expect the template to be rendered with
    an implementation of Jinja in another programming language that does
    not have a ``.items()`` method on its mapping type.

    .. code-block:: html+jinja

        <dl>
        {% for key, value in my_dict|items %}
            <dt>{{ key }}
            <dd>{{ value }}
        {% endfor %}
        </dl>

    .. versionadded:: 3.1
    """
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

@property
def length(self) -> int:
    """Length of the iterable.

    If the iterable is a generator or otherwise does not have a
    size, it is eagerly evaluated to get a size.
    """
    if self._length is not None:
        return self._length

    try:
        self._length = len(self._iterable)  # type: ignore
    except TypeError:
        iterable = list(self._iterator)
        self._iterator = self._to_iterator(iterable)
        self._length = len(iterable) + self.index + (self._after is not missing)

    return self._length

def do_center(value: str, width: int = 80) -> str:
    """Centers the value in a field of a given width."""
    return soft_str(value).center(width)

@staticmethod
def _default_finalize(value: t.Any) -> t.Any:
    return value

@internalcode
def _fail_with_undefined_error(
    self, *args: t.Any, **kwargs: t.Any
) -> "te.NoReturn":
    """Raise an :exc:`UndefinedError` when operations are performed
    on the undefined value.
    """
    raise self._undefined_exception(self._undefined_message)

def do_urlencode(
    value: t.Union[str, t.Mapping[str, t.Any], t.Iterable[t.Tuple[str, t.Any]]],
) -> str:
    """Quote data for use in a URL path or query using UTF-8.

    Basic wrapper around :func:`urllib.parse.quote` when given a
    string, or :func:`urllib.parse.urlencode` for a dict or iterable.

    :param value: Data to quote. A string will be quoted directly. A
        dict or iterable of ``(key, value)`` pairs will be joined as a
        query string.

    When given a string, "/" is not quoted. HTTP servers treat "/" and
    "%2F" equivalently in paths. If you need quoted slashes, use the
    ``|replace("/", "%2F")`` filter.

    .. versionadded:: 2.7
    """
    if isinstance(value, str) or not isinstance(value, abc.Iterable):
        return url_quote(value)

    if isinstance(value, dict):
        items: t.Iterable[t.Tuple[str, t.Any]] = value.items()
    else:
        items = value  # type: ignore

    return "&".join(
        f"{url_quote(k, for_qs=True)}={url_quote(v, for_qs=True)}" for k, v in items
    )

@pass_eval_context
def sync_do_join(
    eval_ctx: "EvalContext",
    value: t.Iterable[t.Any],
    d: str = "",
    attribute: t.Optional[t.Union[str, int]] = None,
) -> str:
    """Return a string which is the concatenation of the strings in the
    sequence. The separator between elements is an empty string per
    default, you can define it with the optional parameter:

    .. sourcecode:: jinja

        {{ [1, 2, 3]|join('|') }}
            -> 1|2|3

        {{ [1, 2, 3]|join }}
            -> 123

    It is also possible to join certain attributes of an object:

    .. sourcecode:: jinja

        {{ users|join(', ', attribute='username') }}

    .. versionadded:: 2.6
       The `attribute` parameter was added.
    """
    if attribute is not None:
        value = map(make_attrgetter(eval_ctx.environment, attribute), value)

    # no automatic escaping?  joining is a lot easier then
    if not eval_ctx.autoescape:
        return str(d).join(map(str, value))

    # if the delimiter doesn't have an html representation we check
    # if any of the items has.  If yes we do a coercion to Markup
    if not hasattr(d, "__html__"):
        value = list(value)
        do_escape = False

        for idx, item in enumerate(value):
            if hasattr(item, "__html__"):
                do_escape = True
            else:
                value[idx] = str(item)

        if do_escape:
            d = escape(d)
        else:
            d = str(d)

        return d.join(value)

    # no html involved, to normal joining
    return soft_str(d).join(map(soft_str, value))

def parse_tuple(
    self,
    simplified: bool = False,
    with_condexpr: bool = True,
    extra_end_rules: t.Optional[t.Tuple[str, ...]] = None,
    explicit_parentheses: bool = False,
    with_namespace: bool = False,
) -> t.Union[nodes.Tuple, nodes.Expr]:
    """Works like `parse_expression` but if multiple expressions are
    delimited by a comma a :class:`~jinja2.nodes.Tuple` node is created.
    This method could also return a regular expression instead of a tuple
    if no commas where found.

    The default parsing mode is a full tuple.  If `simplified` is `True`
    only names and literals are parsed; ``with_namespace`` allows namespace
    attr refs as well. The `no_condexpr` parameter is forwarded to
    :meth:`parse_expression`.

    Because tuples do not require delimiters and may end in a bogus comma
    an extra hint is needed that marks the end of a tuple.  For example
    for loops support tuples between `for` and `in`.  In that case the
    `extra_end_rules` is set to ``['name:in']``.

    `explicit_parentheses` is true if the parsing was triggered by an
    expression in parentheses.  This is used to figure out if an empty
    tuple is a valid expression or not.
    """
    lineno = self.stream.current.lineno
    if simplified:

        def parse() -> nodes.Expr:
            return self.parse_primary(with_namespace=with_namespace)

    else:

        def parse() -> nodes.Expr:
            return self.parse_expression(with_condexpr=with_condexpr)

    args: t.List[nodes.Expr] = []
    is_tuple = False

    while True:
        if args:
            self.stream.expect("comma")
        if self.is_tuple_end(extra_end_rules):
            break
        args.append(parse())
        if self.stream.current.type == "comma":
            is_tuple = True
        else:
            break
        lineno = self.stream.current.lineno

    if not is_tuple:
        if args:
            return args[0]

        # if we don't have explicit parentheses, an empty tuple is
        # not a valid expression.  This would mean nothing (literally
        # nothing) in the spot of an expression would be an empty
        # tuple.
        if not explicit_parentheses:
            self.fail(
                "Expected an expression,"
                f" got {describe_token(self.stream.current)!r}"
            )

    return nodes.Tuple(args, "load", lineno=lineno)

def _min_or_max(
    environment: "Environment",
    value: "t.Iterable[V]",
    func: "t.Callable[..., V]",
    case_sensitive: bool,
    attribute: t.Optional[t.Union[str, int]],
) -> "t.Union[V, Undefined]":
    it = iter(value)

    try:
        first = next(it)
    except StopIteration:
        return environment.undefined("No aggregated item, sequence was empty.")

    key_func = make_attrgetter(
        environment, attribute, postprocess=ignore_case if not case_sensitive else None
    )
    return func(chain([first], it), key=key_func)

@staticmethod
def _default_finalize(value: t.Any) -> t.Any:
    """The default finalize function if the environment isn't
    configured with one. Or, if the environment has one, this is
    called on that function's output for constants.
    """
    return str(value)

def flush_data() -> None:
    if data_buffer:
        lineno = data_buffer[0].lineno
        body.append(nodes.Output(data_buffer[:], lineno=lineno))
        del data_buffer[:]

@property
def nextitem(self) -> t.Union[t.Any, "Undefined"]:
    """The item in the next iteration. Undefined during the last
    iteration.

    Causes the iterable to advance early. See
    :func:`itertools.groupby` for issues this can cause.
    The :func:`jinja-filters.groupby` filter avoids that issue.
    """
    rv = self._peek_next()

    if rv is missing:
        return self._undefined("there is no next item")

    return rv

@pass_environment
def do_last(
    environment: "Environment", seq: "t.Reversible[V]"
) -> "t.Union[V, Undefined]":
    """Return the last item of a sequence.

    Note: Does not work with generators. You may want to explicitly
    convert it to a list:

    .. sourcecode:: jinja

        {{ data | selectattr('name', '==', 'Jinja') | list | last }}
    """
    try:
        return next(iter(reversed(seq)))
    except StopIteration:
        return environment.undefined("No last item, sequence was empty.")

def visit_Output(self, node: nodes.Output, frame: Frame) -> None:
    # If an extends is active, don't render outside a block.
    if frame.require_output_check:
        # A top-level extends is known to exist at compile time.
        if self.has_known_extends:
            return

        self.writeline("if parent_template is None:")
        self.indent()

    finalize = self._make_finalize()
    body: t.List[t.Union[t.List[t.Any], nodes.Expr]] = []

    # Evaluate constants at compile time if possible. Each item in
    # body will be either a list of static data or a node to be
    # evaluated at runtime.
    for child in node.nodes:
        try:
            if not (
                # If the finalize function requires runtime context,
                # constants can't be evaluated at compile time.
                finalize.const
                # Unless it's basic template data that won't be
                # finalized anyway.
                or isinstance(child, nodes.TemplateData)
            ):
                raise nodes.Impossible()

            const = self._output_child_to_const(child, frame, finalize)
        except (nodes.Impossible, Exception):
            # The node was not constant and needs to be evaluated at
            # runtime. Or another error was raised, which is easier
            # to debug at runtime.
            body.append(child)
            continue

        if body and isinstance(body[-1], list):
            body[-1].append(const)
        else:
            body.append([const])

    if frame.buffer is not None:
        if len(body) == 1:
            self.writeline(f"{frame.buffer}.append(")
        else:
            self.writeline(f"{frame.buffer}.extend((")

        self.indent()

    for item in body:
        if isinstance(item, list):
            # A group of constant data to join and output.
            val = self._output_const_repr(item)

            if frame.buffer is None:
                self.writeline("yield " + val)
            else:
                self.writeline(val + ",")
        else:
            if frame.buffer is None:
                self.writeline("yield ", item)
            else:
                self.newline(item)

            # A node to be evaluated at runtime.
            self._output_child_pre(item, frame, finalize)
            self.visit(item, frame)
            self._output_child_post(item, frame, finalize)

            if frame.buffer is not None:
                self.write(",")

    if frame.buffer is not None:
        self.outdent()
        self.writeline(")" if len(body) == 1 else "))")

    if frame.require_output_check:
        self.outdent()

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> t.Dict[str, t.Any]:
    """Based on the runtime locals, get the context that would be
    available at that point in the template.
    """
    # Start with the current template context.
    ctx: t.Optional[Context] = real_locals.get("context")

    if ctx is not None:
        data: t.Dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: t.Dict[str, t.Tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

def _make_finalize(self) -> _FinalizeInfo:
    """Build the finalize function to be used on constants and at
    runtime. Cached so it's only created once for all output nodes.

    Returns a ``namedtuple`` with the following attributes:

    ``const``
        A function to finalize constant data at compile time.

    ``src``
        Source code to output around nodes to be evaluated at
        runtime.
    """
    if self._finalize is not None:
        return self._finalize

    finalize: t.Optional[t.Callable[..., t.Any]]
    finalize = default = self._default_finalize
    src = None

    if self.environment.finalize:
        src = "environment.finalize("
        env_finalize = self.environment.finalize
        pass_arg = {
            _PassArg.context: "context",
            _PassArg.eval_context: "context.eval_ctx",
            _PassArg.environment: "environment",
        }.get(
            _PassArg.from_obj(env_finalize)  # type: ignore
        )
        finalize = None

        if pass_arg is None:

            def finalize(value: t.Any) -> t.Any:  # noqa: F811
                return default(env_finalize(value))

        else:
            src = f"{src}{pass_arg}, "

            if pass_arg == "environment":

                def finalize(value: t.Any) -> t.Any:  # noqa: F811
                    return default(env_finalize(self.environment, value))

    self._finalize = self._FinalizeInfo(finalize, src)
    return self._finalize

def create_cache(
    size: int,
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Return the cache class for the given size."""
    if size == 0:
        return None

    if size < 0:
        return {}

    return LRUCache(size)  # type: ignore

def iter_child_nodes(
    self,
    exclude: t.Optional[t.Container[str]] = None,
    only: t.Optional[t.Container[str]] = None,
) -> t.Iterator["Node"]:
    """Iterates over all direct child nodes of the node.  This iterates
    over all fields and yields the values of they are nodes.  If the value
    of a field is a list all the nodes in that list are returned.
    """
    for _, item in self.iter_fields(exclude, only):
        if isinstance(item, list):
            for n in item:
                if isinstance(n, Node):
                    yield n
        elif isinstance(item, Node):
            yield item

def generate_lorem_ipsum(
    n: int = 5, html: bool = True, min: int = 20, max: int = 100
) -> str:
    """Generate some lorem ipsum for the template."""
    from .constants import LOREM_IPSUM_WORDS

    words = LOREM_IPSUM_WORDS.split()
    result = []

    for _ in range(n):
        next_capitalized = True
        last_comma = last_fullstop = 0
        word = None
        last = None
        p = []

        # each paragraph contains out of 20 to 100 words.
        for idx, _ in enumerate(range(randrange(min, max))):
            while True:
                word = choice(words)
                if word != last:
                    last = word
                    break
            if next_capitalized:
                word = word.capitalize()
                next_capitalized = False
            # add commas
            if idx - randrange(3, 8) > last_comma:
                last_comma = idx
                last_fullstop += 2
                word += ","
            # add end of sentences
            if idx - randrange(10, 20) > last_fullstop:
                last_comma = last_fullstop = idx
                word += "."
                next_capitalized = True
            p.append(word)

        # ensure that the paragraph ends with a dot.
        p_str = " ".join(p)

        if p_str.endswith(","):
            p_str = p_str[:-1] + "."
        elif not p_str.endswith("."):
            p_str += "."

        result.append(p_str)

    if not html:
        return "\n\n".join(result)
    return markupsafe.Markup(
        "\n".join(f"<p>{markupsafe.escape(x)}</p>" for x in result)
    )

@internalcode
@pass_eval_context
def __call__(self, *args: t.Any, **kwargs: t.Any) -> str:
    # This requires a bit of explanation,  In the past we used to
    # decide largely based on compile-time information if a macro is
    # safe or unsafe.  While there was a volatile mode it was largely
    # unused for deciding on escaping.  This turns out to be
    # problematic for macros because whether a macro is safe depends not
    # on the escape mode when it was defined, but rather when it was used.
    #
    # Because however we export macros from the module system and
    # there are historic callers that do not pass an eval context (and
    # will continue to not pass one), we need to perform an instance
    # check here.
    #
    # This is considered safe because an eval context is not a valid
    # argument to callables otherwise anyway.  Worst case here is
    # that if no eval context is passed we fall back to the compile
    # time autoescape flag.
    if args and isinstance(args[0], EvalContext):
        autoescape = args[0].autoescape
        args = args[1:]
    else:
        autoescape = self._default_autoescape

    # try to consume the positional arguments
    arguments = list(args[: self._argument_count])
    off = len(arguments)

    # For information why this is necessary refer to the handling
    # of caller in the `macro_body` handler in the compiler.
    found_caller = False

    # if the number of arguments consumed is not the number of
    # arguments expected we start filling in keyword arguments
    # and defaults.
    if off != self._argument_count:
        for name in self.arguments[len(arguments) :]:
            try:
                value = kwargs.pop(name)
            except KeyError:
                value = missing
            if name == "caller":
                found_caller = True
            arguments.append(value)
    else:
        found_caller = self.explicit_caller

    # it's important that the order of these arguments does not change
    # if not also changed in the compiler's `function_scoping` method.
    # the order is caller, keyword arguments, positional arguments!
    if self.caller and not found_caller:
        caller = kwargs.pop("caller", None)
        if caller is None:
            caller = self._environment.undefined("No caller defined", name="caller")
        arguments.append(caller)

    if self.catch_kwargs:
        arguments.append(kwargs)
    elif kwargs:
        if "caller" in kwargs:
            raise TypeError(
                f"macro {self.name!r} was invoked with two values for the special"
                " caller argument. This is most likely a bug."
            )
        raise TypeError(
            f"macro {self.name!r} takes no keyword argument {next(iter(kwargs))!r}"
        )
    if self.catch_varargs:
        arguments.append(args[self._argument_count :])
    elif len(args) > self._argument_count:
        raise TypeError(
            f"macro {self.name!r} takes not more than"
            f" {len(self.arguments)} argument(s)"
        )

    return self._invoke(arguments, autoescape)

