def __delitem__(self, key: t.Any) -> None:
    """Remove an item from the cache dict.
    Raise a `KeyError` if it does not exist.
    """
    with self._wlock:
        del self._mapping[key]

        try:
            self._remove(key)
        except ValueError:
            pass

def __contains__(self, key: t.Any) -> bool:
    """Check if a key exists in this cache."""
    return key in self._mapping

def setdefault(self, key: t.Any, default: t.Any = None) -> t.Any:
    """Set `default` if the key is not in the cache otherwise
    leave unchanged. Return the value of this key.
    """
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default

def copy_cache(
    cache: t.Optional[t.MutableMapping[t.Any, t.Any]],
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Create an empty copy of the given cache."""
    if cache is None:
        return None

    if type(cache) is dict:  # noqa E721
        return {}

    return LRUCache(cache.capacity)  # type: ignore

def __init__(self, capacity: int) -> None:
    self.capacity = capacity
    self._mapping: t.Dict[t.Any, t.Any] = {}
    self._queue: te.Deque[t.Any] = deque()
    self._postinit()

def __reversed__(self) -> t.Iterator[t.Any]:
    """Iterate over the keys in the cache dict, oldest items
    coming first.
    """
    return iter(tuple(self._queue))

def create_cache(
    size: int,
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Return the cache class for the given size."""
    if size == 0:
        return None

    if size < 0:
        return {}

    return LRUCache(size)  # type: ignore

def keys(self) -> t.Iterable[t.Any]:
    """Return a list of all keys ordered by most recent usage."""
    return list(self)

def __len__(self) -> int:
    """Return the current size of the cache."""
    return len(self._mapping)

def get(self, key: t.Any, default: t.Any = None) -> t.Any:
    """Return an item from the cache dict or `default`"""
    try:
        return self[key]
    except KeyError:
        return default

def set_bucket(self, bucket: Bucket) -> None:
    """Put the bucket into the cache."""
    self.dump_bytecode(bucket)

def __setstate__(self, d: t.Mapping[str, t.Any]) -> None:
    self.__dict__.update(d)
    self._postinit()

def dump_bytecode(self, bucket: Bucket) -> None:
    key = self.prefix + bucket.key
    value = bucket.bytecode_to_string()

    try:
        if self.timeout is not None:
            self.client.set(key, value, self.timeout)
        else:
            self.client.set(key, value)
    except Exception:
        if not self.ignore_memcache_errors:
            raise

def __getstate__(self) -> t.Mapping[str, t.Any]:
    return {
        "capacity": self.capacity,
        "_mapping": self._mapping,
        "_queue": self._queue,
    }

def reset(self) -> None:
    """Resets the bucket (unloads the bytecode)."""
    self.code: t.Optional[CodeType] = None

def load_bytecode(self, bucket: Bucket) -> None:
    try:
        code = self.client.get(self.prefix + bucket.key)
    except Exception:
        if not self.ignore_memcache_errors:
            raise
    else:
        bucket.bytecode_from_string(code)

def get_cache_key(
    self, name: str, filename: t.Optional[t.Union[str]] = None
) -> str:
    """Returns the unique hash key for this template name."""
    hash = sha1(name.encode("utf-8"))

    if filename is not None:
        hash.update(f"|{filename}".encode())

    return hash.hexdigest()

def values(self) -> t.Iterable[t.Any]:
    """Return a list of all values."""
    return [x[1] for x in self.items()]

@internalcode
def _load_template(
    self, name: str, globals: t.Optional[t.MutableMapping[str, t.Any]]
) -> "Template":
    if self.loader is None:
        raise TypeError("no loader for this environment specified")
    cache_key = (weakref.ref(self.loader), name)
    if self.cache is not None:
        template = self.cache.get(cache_key)
        if template is not None and (
            not self.auto_reload or template.is_up_to_date
        ):
            # template.globals is a ChainMap, modifying it will only
            # affect the template, not the environment globals.
            if globals:
                template.globals.update(globals)

            return template

    template = self.loader.load(self, name, self.make_globals(globals))

    if self.cache is not None:
        self.cache[cache_key] = template
    return template

def branch_update(self, branch_symbols: t.Sequence["Symbols"]) -> None:
    stores: t.Set[str] = set()

    for branch in branch_symbols:
        stores.update(branch.stores)

    stores.difference_update(self.stores)

    for sym in branch_symbols:
        self.refs.update(sym.refs)
        self.loads.update(sym.loads)
        self.stores.update(sym.stores)

    for name in stores:
        target = self.find_ref(name)
        assert target is not None, "should not happen"

        if self.parent is not None:
            outer_target = self.parent.find_ref(name)
            if outer_target is not None:
                self.loads[target] = (VAR_LOAD_ALIAS, outer_target)
                continue
        self.loads[target] = (VAR_LOAD_RESOLVE, name)

def revert(self, old: t.Mapping[str, t.Any]) -> None:
    self.__dict__.clear()
    self.__dict__.update(old)

def is_safe_attribute(self, obj: t.Any, attr: str, value: t.Any) -> bool:
    if not super().is_safe_attribute(obj, attr, value):
        return False

    return not modifies_known_mutable(obj, attr)

def __init__(
    self, directory: t.Optional[str] = None, pattern: str = "__jinja2_%s.cache"
) -> None:
    if directory is None:
        directory = self._get_default_cache_dir()
    self.directory = directory
    self.pattern = pattern

@property
def is_up_to_date(self) -> bool:
    """If this variable is `False` there is a newer version available."""
    if self._uptodate is None:
        return True
    return self._uptodate()

def clear(self) -> None:
    # imported lazily here because google app-engine doesn't support
    # write access on the file system and the function does not exist
    # normally.
    from os import remove

    files = fnmatch.filter(os.listdir(self.directory), self.pattern % ("*",))
    for filename in files:
        try:
            remove(os.path.join(self.directory, filename))
        except OSError:
            pass

@pass_eval_context
def do_replace(
    eval_ctx: "EvalContext", s: str, old: str, new: str, count: t.Optional[int] = None
) -> str:
    """Return a copy of the value with all occurrences of a substring
    replaced with a new one. The first argument is the substring
    that should be replaced, the second is the replacement string.
    If the optional third argument ``count`` is given, only the first
    ``count`` occurrences are replaced:

    .. sourcecode:: jinja

        {{ "Hello World"|replace("Hello", "Goodbye") }}
            -> Goodbye World

        {{ "aaaaargh"|replace("a", "d'oh, ", 2) }}
            -> d'oh, d'oh, aaargh
    """
    if count is None:
        count = -1

    if not eval_ctx.autoescape:
        return str(s).replace(str(old), str(new), count)

    if (
        hasattr(old, "__html__")
        or hasattr(new, "__html__")
        and not hasattr(s, "__html__")
    ):
        s = escape(s)
    else:
        s = soft_str(s)

    return s.replace(soft_str(old), soft_str(new), count)

def _unsafe_dir() -> "te.NoReturn":
    raise RuntimeError(
        "Cannot determine safe temp directory.  You "
        "need to explicitly provide one."
    )

@async_variant(sync_do_unique)  # type: ignore
async def do_unique(
    environment: "Environment",
    value: "t.Union[t.AsyncIterable[V], t.Iterable[V]]",
    case_sensitive: bool = False,
    attribute: t.Optional[t.Union[str, int]] = None,
) -> "t.Iterator[V]":
    return sync_do_unique(
        environment, await auto_to_list(value), case_sensitive, attribute
    )

