    self._mapping: t.Dict[t.Any, t.Any] = {}
    self._queue: te.Deque[t.Any] = deque()
    self._postinit()

def get(self, key: t.Any, default: t.Any = None) -> t.Any:
    """Return an item from the cache dict or `default`"""
    try:
        return self[key]
    except KeyError:
        return default

def __contains__(self, key: t.Any) -> bool:
    """Check if a key exists in this cache."""
    return key in self._mapping

def setdefault(self, key: t.Any, default: t.Any = None) -> t.Any:
    """Set `default` if the key is not in the cache otherwise
    leave unchanged. Return the value of this key.
    """
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default

def __getstate__(self) -> t.Mapping[str, t.Any]:
    return {
        "capacity": self.capacity,
        "_mapping": self._mapping,
        "_queue": self._queue,
    }

def get_cache_key(
    self, name: str, filename: t.Optional[t.Union[str]] = None
) -> str:
    """Returns the unique hash key for this template name."""
    hash = sha1(name.encode("utf-8"))

    if filename is not None:
        hash.update(f"|{filename}".encode())

    return hash.hexdigest()

@internalcode
def _load_template(
    self, name: str, globals: t.Optional[t.MutableMapping[str, t.Any]]
) -> "Template":
    if self.loader is None:
        raise TypeError("no loader for this environment specified")
    cache_key = (weakref.ref(self.loader), name)
    if self.cache is not None:
        template = self.cache.get(cache_key)
        if template is not None and (
            not self.auto_reload or template.is_up_to_date
        ):
            # template.globals is a ChainMap, modifying it will only
            # affect the template, not the environment globals.
            if globals:
                template.globals.update(globals)

            return template

    template = self.loader.load(self, name, self.make_globals(globals))

    if self.cache is not None:
        self.cache[cache_key] = template
    return template

def set_bucket(self, bucket: Bucket) -> None:
    """Put the bucket into the cache."""
    self.dump_bytecode(bucket)

def __setstate__(self, d: t.Mapping[str, t.Any]) -> None:
    self.__dict__.update(d)
    self._postinit()

@pass_eval_context
def do_replace(
    eval_ctx: "EvalContext", s: str, old: str, new: str, count: t.Optional[int] = None
) -> str:
    """Return a copy of the value with all occurrences of a substring
    replaced with a new one. The first argument is the substring
    that should be replaced, the second is the replacement string.
    If the optional third argument ``count`` is given, only the first
    ``count`` occurrences are replaced:

    .. sourcecode:: jinja

        {{ "Hello World"|replace("Hello", "Goodbye") }}
            -> Goodbye World

        {{ "aaaaargh"|replace("a", "d'oh, ", 2) }}
            -> d'oh, d'oh, aaargh
    """
    if count is None:
        count = -1

    if not eval_ctx.autoescape:
        return str(s).replace(str(old), str(new), count)

    if (
        hasattr(old, "__html__")
        or hasattr(new, "__html__")
        and not hasattr(s, "__html__")
    ):
        s = escape(s)
    else:
        s = soft_str(s)

    return s.replace(soft_str(old), soft_str(new), count)

def create_cache(
    size: int,
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Return the cache class for the given size."""
    if size == 0:
        return None

    if size < 0:
        return {}

    return LRUCache(size)  # type: ignore

def keys(self) -> t.Iterable[t.Any]:
    """Return a list of all keys ordered by most recent usage."""
    return list(self)

def __len__(self) -> int:
    """Return the current size of the cache."""
    return len(self._mapping)

def do_items(value: t.Union[t.Mapping[K, V], Undefined]) -> t.Iterator[t.Tuple[K, V]]:
    """Return an iterator over the ``(key, value)`` items of a mapping.

    ``x|items`` is the same as ``x.items()``, except if ``x`` is
    undefined an empty iterator is returned.

    This filter is useful if you expect the template to be rendered with
    an implementation of Jinja in another programming language that does
    not have a ``.items()`` method on its mapping type.

    .. code-block:: html+jinja

        <dl>
        {% for key, value in my_dict|items %}
            <dt>{{ key }}
            <dd>{{ value }}
        {% endfor %}
        </dl>

    .. versionadded:: 3.1
    """
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

        # update brace/parentheses balance
        if tokens == TOKEN_OPERATOR:
            if data == "{":
                balancing_stack.append("}")
            elif data == "(":
                balancing_stack.append(")")
            elif data == "[":
                balancing_stack.append("]")
            elif data in ("}", ")", "]"):
                if not balancing_stack:
                    raise TemplateSyntaxError(
                        f"unexpected '{data}'", lineno, name, filename
                    )

                expected_op = balancing_stack.pop()

                if expected_op != data:
                    raise TemplateSyntaxError(
                        f"unexpected '{data}', expected '{expected_op}'",
                        lineno,
                        name,
                        filename,
                    )

        # yield items
        if data or tokens not in ignore_if_empty:
            yield lineno, tokens, data

        lineno += data.count("\n")

    line_starting = m.group()[-1:] == "\n"
    # fetch new position into new variable so that we can check
    # if there is a internal parsing error which would result
    # in an infinite loop
    pos2 = m.end()

    # handle state changes
    if new_state is not None:
        # remove the uppermost state
        if new_state == "#pop":
            stack.pop()
        # resolve the new state by group checking
        elif new_state == "#bygroup":
            for key, value in m.groupdict().items():
                if value is not None:
                    stack.append(key)
                    break
            else:
                raise RuntimeError(
                    f"{regex!r} wanted to resolve the new state dynamically"
                    f" but no group matched"
                )
        # direct state name given
        else:
            stack.append(new_state)

        statetokens = self.rules[stack[-1]]
    # we are still at the same position and no stack change.
    # this means a loop without break condition, avoid that and
    # raise error
    elif pos2 == pos:
        raise RuntimeError(
            f"{regex!r} yielded empty string without stack change"
        )

    # publish new function and start again
    pos = pos2
    break
# if loop terminated without break we haven't found a single match
# either we are at the end of the file or we have a problem
else:
    # end of text
    if pos >= source_length:
        return

    # something went wrong
    raise TemplateSyntaxError(
        f"unexpected char {source[pos]!r} at {pos}", lineno, name, filename
    )

def dump_bytecode(self, bucket: Bucket) -> None:
    key = self.prefix + bucket.key
    value = bucket.bytecode_to_string()

    try:
        if self.timeout is not None:
            self.client.set(key, value, self.timeout)
        else:
            self.client.set(key, value)
    except Exception:
        if not self.ignore_memcache_errors:
            raise

@internalcode
def __getattr__(self, name: str) -> t.Any:
    # Raise AttributeError on requests for names that appear to be unimplemented
    # dunder methods to keep Python's internal protocol probing behaviors working
    # properly in cases where another exception type could cause unexpected or
    # difficult-to-diagnose failures.
    if name[:2] == "__" and name[-2:] == "__":
        raise AttributeError(name)

    return self._fail_with_undefined_error()

def parse_tuple(
    self,
    simplified: bool = False,
    with_condexpr: bool = True,
    extra_end_rules: t.Optional[t.Tuple[str, ...]] = None,
    explicit_parentheses: bool = False,
    with_namespace: bool = False,
) -> t.Union[nodes.Tuple, nodes.Expr]:
    """Works like `parse_expression` but if multiple expressions are
    delimited by a comma a :class:`~jinja2.nodes.Tuple` node is created.
    This method could also return a regular expression instead of a tuple
    if no commas where found.

    The default parsing mode is a full tuple.  If `simplified` is `True`
    only names and literals are parsed; ``with_namespace`` allows namespace
    attr refs as well. The `no_condexpr` parameter is forwarded to
    :meth:`parse_expression`.

    Because tuples do not require delimiters and may end in a bogus comma
    an extra hint is needed that marks the end of a tuple.  For example
    for loops support tuples between `for` and `in`.  In that case the
    `extra_end_rules` is set to ``['name:in']``.

    `explicit_parentheses` is true if the parsing was triggered by an
    expression in parentheses.  This is used to figure out if an empty
    tuple is a valid expression or not.
    """
    lineno = self.stream.current.lineno
    if simplified:

        def parse() -> nodes.Expr:
            return self.parse_primary(with_namespace=with_namespace)

    else:

        def parse() -> nodes.Expr:
            return self.parse_expression(with_condexpr=with_condexpr)

    args: t.List[nodes.Expr] = []
    is_tuple = False

    while True:
        if args:
            self.stream.expect("comma")
        if self.is_tuple_end(extra_end_rules):
            break
        args.append(parse())
        if self.stream.current.type == "comma":
            is_tuple = True
        else:
            break
        lineno = self.stream.current.lineno

    if not is_tuple:
        if args:
            return args[0]

        # if we don't have explicit parentheses, an empty tuple is
        # not a valid expression.  This would mean nothing (literally
        # nothing) in the spot of an expression would be an empty
        # tuple.
        if not explicit_parentheses:
            self.fail(
                "Expected an expression,"
                f" got {describe_token(self.stream.current)!r}"
            )

    return nodes.Tuple(args, "load", lineno=lineno)

def reset(self) -> None:
    """Resets the bucket (unloads the bytecode)."""
    self.code: t.Optional[CodeType] = None

def load_bytecode(self, bucket: Bucket) -> None:
    try:
        code = self.client.get(self.prefix + bucket.key)
    except Exception:
        if not self.ignore_memcache_errors:
            raise
    else:
        bucket.bytecode_from_string(code)

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

def _get_default_cache_dir(self) -> str:
    def _unsafe_dir() -> "te.NoReturn":
        raise RuntimeError(
            "Cannot determine safe temp directory.  You "
            "need to explicitly provide one."
        )

    tmpdir = tempfile.gettempdir()

    # On windows the temporary directory is used specific unless
    # explicitly forced otherwise.  We can just use that.
    if os.name == "nt":
        return tmpdir
    if not hasattr(os, "getuid"):
        _unsafe_dir()

    dirname = f"_jinja2-cache-{os.getuid()}"
    actual_dir = os.path.join(tmpdir, dirname)

    try:
        os.mkdir(actual_dir, stat.S_IRWXU)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise
    try:
        os.chmod(actual_dir, stat.S_IRWXU)
        actual_dir_stat = os.lstat(actual_dir)
        if (
            actual_dir_stat.st_uid != os.getuid()
            or not stat.S_ISDIR(actual_dir_stat.st_mode)
            or stat.S_IMODE(actual_dir_stat.st_mode) != stat.S_IRWXU
        ):
            _unsafe_dir()
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

    actual_dir_stat = os.lstat(actual_dir)
    if (
        actual_dir_stat.st_uid != os.getuid()
        or not stat.S_ISDIR(actual_dir_stat.st_mode)
        or stat.S_IMODE(actual_dir_stat.st_mode) != stat.S_IRWXU
    ):
        _unsafe_dir()

    return actual_dir

