        # something else we don't care about, we could warn here
        else:
            yield None

def uptodate() -> bool:
    try:
        return os.path.getmtime(filename) == mtime
    except OSError:
        return False

def copy_cache(
    cache: t.Optional[t.MutableMapping[t.Any, t.Any]],
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Create an empty copy of the given cache."""
    if cache is None:
        return None

    if type(cache) is dict:  # noqa E721
        return {}

    return LRUCache(cache.capacity)  # type: ignore

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

@internalcode
def load(
    self,
    environment: "Environment",
    name: str,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    key = self.get_template_key(name)
    module = f"{self.package_name}.{key}"
    mod = getattr(self.module, module, None)

    if mod is None:
        try:
            mod = __import__(module, None, None, ["root"])
        except ImportError as e:
            raise TemplateNotFound(name) from e

        # remove the entry from sys.modules, we only want the attribute
        # on the module object we have stored on the loader.
        sys.modules.pop(module, None)

    if globals is None:
        globals = {}

    return environment.template_class.from_module_dict(
        environment, mod.__dict__, globals
    )

@property
def is_up_to_date(self) -> bool:
    """If this variable is `False` there is a newer version available."""
    if self._uptodate is None:
        return True
    return self._uptodate()

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, str, t.Callable[[], bool]]:
    pieces = split_template_path(template)

    for searchpath in self.searchpath:
        # Use posixpath even on Windows to avoid "drive:" or UNC
        # segments breaking out of the search directory.
        filename = posixpath.join(searchpath, *pieces)

        if os.path.isfile(filename):
            break
    else:
        plural = "path" if len(self.searchpath) == 1 else "paths"
        paths_str = ", ".join(repr(p) for p in self.searchpath)
        raise TemplateNotFound(
            template,
            f"{template!r} not found in search {plural}: {paths_str}",
        )

    with open(filename, encoding=self.encoding) as f:
        contents = f.read()

    mtime = os.path.getmtime(filename)

    def uptodate() -> bool:
        try:
            return os.path.getmtime(filename) == mtime
        except OSError:
            return False

    # Use normpath to convert Windows altsep to sep.
    return contents, os.path.normpath(filename), uptodate

@internalcode
def __getattr__(self, name: str) -> t.Any:
    # Raise AttributeError on requests for names that appear to be unimplemented
    # dunder methods to keep Python's internal protocol probing behaviors working
    # properly in cases where another exception type could cause unexpected or
    # difficult-to-diagnose failures.
    if name[:2] == "__" and name[-2:] == "__":
        raise AttributeError(name)

    return self._fail_with_undefined_error()

def do_mark_safe(value: str) -> Markup:
    """Mark the value as safe which means that in an environment with automatic
    escaping enabled this variable will not be escaped.
    """
    return Markup(value)

@staticmethod
def get_template_key(name: str) -> str:
    return "tmpl_" + sha1(name.encode("utf-8")).hexdigest()

def create_cache(
    size: int,
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Return the cache class for the given size."""
    if size == 0:
        return None

    if size < 0:
        return {}

    return LRUCache(size)  # type: ignore

async def render_async(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This works similar to :meth:`render` but returns a coroutine
    that when awaited returns the entire rendered template string.  This
    requires the async feature to be enabled.

    Example usage::

        await template.render_async(knights='that say nih; asynchronously')
    """
    if not self.environment.is_async:
        raise RuntimeError(
            "The environment was not created with async mode enabled."
        )

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(  # type: ignore
            [n async for n in self.root_render_func(ctx)]  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

def list_templates(self) -> t.List[str]:
    results: t.List[str] = []

    if self._archive is None:
        # Package is a directory.
        offset = len(self._template_root)

        for dirpath, _, filenames in os.walk(self._template_root):
            dirpath = dirpath[offset:].lstrip(os.path.sep)
            results.extend(
                os.path.join(dirpath, name).replace(os.path.sep, "/")
                for name in filenames
            )
    else:
        files = _get_zipimporter_files(self._loader)

        # Package is a zip file.
        prefix = (
            self._template_root[len(self._archive) :].lstrip(os.path.sep)
            + os.path.sep
        )
        offset = len(prefix)

        for name in files:
            # Find names under the templates directory that aren't directories.
            if name.startswith(prefix) and name[-1] != os.path.sep:
                results.append(name[offset:].replace(os.path.sep, "/"))

    results.sort()
    return results

def remove_silent() -> None:
    try:
        os.remove(f.name)
    except OSError:
        # Another process may have called clear(). On Windows,
        # another program may be holding the file open.
        pass

@internalcode
def load(
    self,
    environment: "Environment",
    name: str,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    for loader in self.loaders:
        try:
            return loader.load(environment, name, globals)
        except TemplateNotFound:
            pass
    raise TemplateNotFound(name)

@internalcode
@pass_eval_context
def __call__(self, *args: t.Any, **kwargs: t.Any) -> str:
    # This requires a bit of explanation,  In the past we used to
    # decide largely based on compile-time information if a macro is
    # safe or unsafe.  While there was a volatile mode it was largely
    # unused for deciding on escaping.  This turns out to be
    # problematic for macros because whether a macro is safe depends not
    # on the escape mode when it was defined, but rather when it was used.
    #
    # Because however we export macros from the module system and
    # there are historic callers that do not pass an eval context (and
    # will continue to not pass one), we need to perform an instance
    # check here.
    #
    # This is considered safe because an eval context is not a valid
    # argument to callables otherwise anyway.  Worst case here is
    # that if no eval context is passed we fall back to the compile
    # time autoescape flag.
    if args and isinstance(args[0], EvalContext):
        autoescape = args[0].autoescape
        args = args[1:]
    else:
        autoescape = self._default_autoescape

    # try to consume the positional arguments
    arguments = list(args[: self._argument_count])
    off = len(arguments)

    # For information why this is necessary refer to the handling
    # of caller in the `macro_body` handler in the compiler.
    found_caller = False

    # if the number of arguments consumed is not the number of
    # arguments expected we start filling in keyword arguments
    # and defaults.
    if off != self._argument_count:
        for name in self.arguments[len(arguments) :]:
            try:
                value = kwargs.pop(name)
            except KeyError:
                value = missing
            if name == "caller":
                found_caller = True
            arguments.append(value)
    else:
        found_caller = self.explicit_caller

    # it's important that the order of these arguments does not change
    # if not also changed in the compiler's `function_scoping` method.
    # the order is caller, keyword arguments, positional arguments!
    if self.caller and not found_caller:
        caller = kwargs.pop("caller", None)
        if caller is None:
            caller = self._environment.undefined("No caller defined", name="caller")
        arguments.append(caller)

    if self.catch_kwargs:
        arguments.append(kwargs)
    elif kwargs:
        if "caller" in kwargs:
            raise TypeError(
                f"macro {self.name!r} was invoked with two values for the special"
                " caller argument. This is most likely a bug."
            )
        raise TypeError(
            f"macro {self.name!r} takes no keyword argument {next(iter(kwargs))!r}"
        )
    if self.catch_varargs:
        arguments.append(args[self._argument_count :])
    elif len(args) > self._argument_count:
        raise TypeError(
            f"macro {self.name!r} takes not more than"
            f" {len(self.arguments)} argument(s)"
        )

    return self._invoke(arguments, autoescape)

def clear(self) -> None:
    # imported lazily here because google app-engine doesn't support
    # write access on the file system and the function does not exist
    # normally.
    from os import remove

    files = fnmatch.filter(os.listdir(self.directory), self.pattern % ("*",))
    for filename in files:
        try:
            remove(os.path.join(self.directory, filename))
        except OSError:
            pass

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, None, t.Callable[[], bool]]:
    if template in self.mapping:
        source = self.mapping[template]
        return source, None, lambda: source == self.mapping.get(template)
    raise TemplateNotFound(template)

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    loader, name = self.get_loader(template)
    try:
        return loader.get_source(environment, name)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(template) from e

def visit_Output(self, node: nodes.Output, frame: Frame) -> None:
    # If an extends is active, don't render outside a block.
    if frame.require_output_check:
        # A top-level extends is known to exist at compile time.
        if self.has_known_extends:
            return

        self.writeline("if parent_template is None:")
        self.indent()

    finalize = self._make_finalize()
    body: t.List[t.Union[t.List[t.Any], nodes.Expr]] = []

    # Evaluate constants at compile time if possible. Each item in
    # body will be either a list of static data or a node to be
    # evaluated at runtime.
    for child in node.nodes:
        try:
            if not (
                # If the finalize function requires runtime context,
                # constants can't be evaluated at compile time.
                finalize.const
                # Unless it's basic template data that won't be
                # finalized anyway.
                or isinstance(child, nodes.TemplateData)
            ):
                raise nodes.Impossible()

            const = self._output_child_to_const(child, frame, finalize)
        except (nodes.Impossible, Exception):
            # The node was not constant and needs to be evaluated at
            # runtime. Or another error was raised, which is easier
            # to debug at runtime.
            body.append(child)
            continue

        if body and isinstance(body[-1], list):
            body[-1].append(const)
        else:
            body.append([const])

    if frame.buffer is not None:
        if len(body) == 1:
            self.writeline(f"{frame.buffer}.append(")
        else:
            self.writeline(f"{frame.buffer}.extend((")

        self.indent()

    for item in body:
        if isinstance(item, list):
            # A group of constant data to join and output.
            val = self._output_const_repr(item)

            if frame.buffer is None:
                self.writeline("yield " + val)
            else:
                self.writeline(val + ",")
        else:
            if frame.buffer is None:
                self.writeline("yield ", item)
            else:
                self.newline(item)

            # A node to be evaluated at runtime.
            self._output_child_pre(item, frame, finalize)
            self.visit(item, frame)
            self._output_child_post(item, frame, finalize)

            if frame.buffer is not None:
                self.write(",")

    if frame.buffer is not None:
        self.outdent()
        self.writeline(")" if len(body) == 1 else "))")

    if frame.require_output_check:
        self.outdent()

def list_templates(self) -> t.List[str]:
    found = set()
    for searchpath in self.searchpath:
        walk_dir = os.walk(searchpath, followlinks=self.followlinks)
        for dirpath, _, filenames in walk_dir:
            for filename in filenames:
                template = (
                    os.path.join(dirpath, filename)[len(searchpath) :]
                    .strip(os.path.sep)
                    .replace(os.path.sep, "/")
                )
                if template[:2] == "./":
                    template = template[2:]
                if template not in found:
                    found.add(template)
    return sorted(found)

def get_cache_key(
    self, name: str, filename: t.Optional[t.Union[str]] = None
) -> str:
    """Returns the unique hash key for this template name."""
    hash = sha1(name.encode("utf-8"))

    if filename is not None:
        hash.update(f"|{filename}".encode())

    return hash.hexdigest()

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    for loader in self.loaders:
        try:
            return loader.get_source(environment, template)
        except TemplateNotFound:
            pass
    raise TemplateNotFound(template)

