def load(
    self,
    environment: "Environment",
    name: str,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    loader, local_name = self.get_loader(name)
    try:
        return loader.load(environment, local_name, globals)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(name) from e

@internalcode
def __call__(self) -> str:
    if self._context.environment.is_async:
        return self._async_call()  # type: ignore

    rv = self._context.environment.concat(  # type: ignore
        self._stack[self._depth](self._context)
    )

    if self._context.eval_ctx.autoescape:
        return Markup(rv)

    return rv

@internalcode
def get_or_select_template(
    self,
    template_name_or_list: t.Union[
        str, "Template", t.List[t.Union[str, "Template"]]
    ],
    parent: t.Optional[str] = None,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    """Use :meth:`select_template` if an iterable of template names
    is given, or :meth:`get_template` if one name is given.

    .. versionadded:: 2.3
    """
    if isinstance(template_name_or_list, (str, Undefined)):
        return self.get_template(template_name_or_list, parent, globals)
    elif isinstance(template_name_or_list, Template):
        return template_name_or_list
    return self.select_template(template_name_or_list, parent, globals)

def pop_assign_tracking(self, frame: Frame) -> None:
    """Pops the topmost level for assignment tracking and updates the
    context variables if necessary.
    """
    vars = self._assign_stack.pop()
    if (
        not frame.block_frame
        and not frame.loop_frame
        and not frame.toplevel
        or not vars
    ):
        return
    public_names = [x for x in vars if x[:1] != "_"]
    if len(vars) == 1:
        name = next(iter(vars))
        ref = frame.symbols.ref(name)
        if frame.loop_frame:
            self.writeline(f"_loop_vars[{name!r}] = {ref}")
            return
        if frame.block_frame:
            self.writeline(f"_block_vars[{name!r}] = {ref}")
            return
        self.writeline(f"context.vars[{name!r}] = {ref}")
    else:
        if frame.loop_frame:
            self.writeline("_loop_vars.update({")
        elif frame.block_frame:
            self.writeline("_block_vars.update({")
        else:
            self.writeline("context.vars.update({")
        for idx, name in enumerate(sorted(vars)):
            if idx:
                self.write(", ")
            ref = frame.symbols.ref(name)
            self.write(f"{name!r}: {ref}")
        self.write("})")
    if not frame.block_frame and not frame.loop_frame and public_names:
        if len(public_names) == 1:
            self.writeline(f"context.exported_vars.add({public_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, sorted(public_names)))
            self.writeline(f"context.exported_vars.update(({names_str}))")

@internalcode
def call(
    __self,
    __obj: t.Callable[..., t.Any],
    *args: t.Any,
    **kwargs: t.Any,  # noqa: B902
) -> t.Union[t.Any, "Undefined"]:
    """Call the callable with the arguments and keyword arguments
    provided but inject the active context or environment as first
    argument if the callable has :func:`pass_context` or
    :func:`pass_environment`.
    """
    if __debug__:
        __traceback_hide__ = True  # noqa

    # Allow callable classes to take a context
    if (
        hasattr(__obj, "__call__")  # noqa: B004
        and _PassArg.from_obj(__obj.__call__) is not None
    ):
        __obj = __obj.__call__

    pass_arg = _PassArg.from_obj(__obj)

    if pass_arg is _PassArg.context:
        # the active context should have access to variables set in
        # loops and blocks without mutating the context itself
        if kwargs.get("_loop_vars"):
            __self = __self.derived(kwargs["_loop_vars"])
        if kwargs.get("_block_vars"):
            __self = __self.derived(kwargs["_block_vars"])
        args = (__self,) + args
    elif pass_arg is _PassArg.eval_context:
        args = (__self.eval_ctx,) + args
    elif pass_arg is _PassArg.environment:
        args = (__self.environment,) + args

    kwargs.pop("_block_vars", None)
    kwargs.pop("_loop_vars", None)

    try:
        return __obj(*args, **kwargs)
    except StopIteration:
        return __self.environment.undefined(
            "value was undefined because a callable raised a"
            " StopIteration exception"
        )

