            " StopIteration exception"
        )

@internalcode
@pass_eval_context
def __call__(self, *args: t.Any, **kwargs: t.Any) -> str:
    # This requires a bit of explanation,  In the past we used to
    # decide largely based on compile-time information if a macro is
    # safe or unsafe.  While there was a volatile mode it was largely
    # unused for deciding on escaping.  This turns out to be
    # problematic for macros because whether a macro is safe depends not
    # on the escape mode when it was defined, but rather when it was used.
    #
    # Because however we export macros from the module system and
    # there are historic callers that do not pass an eval context (and
    # will continue to not pass one), we need to perform an instance
    # check here.
    #
    # This is considered safe because an eval context is not a valid
    # argument to callables otherwise anyway.  Worst case here is
    # that if no eval context is passed we fall back to the compile
    # time autoescape flag.
    if args and isinstance(args[0], EvalContext):
        autoescape = args[0].autoescape
        args = args[1:]
    else:
        autoescape = self._default_autoescape

    # try to consume the positional arguments
    arguments = list(args[: self._argument_count])
    off = len(arguments)

    # For information why this is necessary refer to the handling
    # of caller in the `macro_body` handler in the compiler.
    found_caller = False

    # if the number of arguments consumed is not the number of
    # arguments expected we start filling in keyword arguments
    # and defaults.
    if off != self._argument_count:
        for name in self.arguments[len(arguments) :]:
            try:
                value = kwargs.pop(name)
            except KeyError:
                value = missing
            if name == "caller":
                found_caller = True
            arguments.append(value)
    else:
        found_caller = self.explicit_caller

    # it's important that the order of these arguments does not change
    # if not also changed in the compiler's `function_scoping` method.
    # the order is caller, keyword arguments, positional arguments!
    if self.caller and not found_caller:
        caller = kwargs.pop("caller", None)
        if caller is None:
            caller = self._environment.undefined("No caller defined", name="caller")
        arguments.append(caller)

    if self.catch_kwargs:
        arguments.append(kwargs)
    elif kwargs:
        if "caller" in kwargs:
            raise TypeError(
                f"macro {self.name!r} was invoked with two values for the special"
                " caller argument. This is most likely a bug."
            )
        raise TypeError(
            f"macro {self.name!r} takes no keyword argument {next(iter(kwargs))!r}"
        )
    if self.catch_varargs:
        arguments.append(args[self._argument_count :])
    elif len(args) > self._argument_count:
        raise TypeError(
            f"macro {self.name!r} takes not more than"
            f" {len(self.arguments)} argument(s)"
        )

    return self._invoke(arguments, autoescape)

@internalcode
def __getattr__(self, name: str) -> t.Any:
    # Raise AttributeError on requests for names that appear to be unimplemented
    # dunder methods to keep Python's internal protocol probing behaviors working
    # properly in cases where another exception type could cause unexpected or
    # difficult-to-diagnose failures.
    if name[:2] == "__" and name[-2:] == "__":
        raise AttributeError(name)

    return self._fail_with_undefined_error()

@internalcode
def _load_template(
    self, name: str, globals: t.Optional[t.MutableMapping[str, t.Any]]
) -> "Template":
    if self.loader is None:
        raise TypeError("no loader for this environment specified")
    cache_key = (weakref.ref(self.loader), name)
    if self.cache is not None:
        template = self.cache.get(cache_key)
        if template is not None and (
            not self.auto_reload or template.is_up_to_date
        ):
            # template.globals is a ChainMap, modifying it will only
            # affect the template, not the environment globals.
            if globals:
                template.globals.update(globals)

            return template

    template = self.loader.load(self, name, self.make_globals(globals))

    if self.cache is not None:
        self.cache[cache_key] = template
    return template

def find_referenced_templates(ast: nodes.Template) -> t.Iterator[t.Optional[str]]:
    """Finds all the referenced templates from the AST.  This will return an
    iterator over all the hardcoded template extensions, inclusions and
    imports.  If dynamic inheritance or inclusion is used, `None` will be
    yielded.

    >>> from jinja2 import Environment, meta
    >>> env = Environment()
    >>> ast = env.parse('{% extends "layout.html" %}{% include helper %}')
    >>> list(meta.find_referenced_templates(ast))
    ['layout.html', None]

    This function is useful for dependency tracking.  For example if you want
    to rebuild parts of the website after a layout template has changed.
    """
    template_name: t.Any

    for node in ast.find_all(_ref_types):
        template: nodes.Expr = node.template  # type: ignore

        if not isinstance(template, nodes.Const):
            # a tuple with some non consts in there
            if isinstance(template, (nodes.Tuple, nodes.List)):
                for template_name in template.items:
                    # something const, only yield the strings and ignore
                    # non-string consts that really just make no sense
                    if isinstance(template_name, nodes.Const):
                        if isinstance(template_name.value, str):
                            yield template_name.value
                    # something dynamic in there
                    else:
                        yield None
            # something dynamic we don't know about here
            else:
                yield None
            continue
        # constant is a basestring, direct template name
        if isinstance(template.value, str):
            yield template.value
        # a tuple or list (latter *should* not happen) made of consts,
        # yield the consts that are strings.  We could warn here for
        # non string values
        elif isinstance(node, nodes.Include) and isinstance(
            template.value, (tuple, list)
        ):
            for template_name in template.value:
                if isinstance(template_name, str):
                    yield template_name
        # something else we don't care about, we could warn here
        else:
            yield None

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    loader, name = self.get_loader(template)
    try:
        return loader.get_source(environment, name)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(template) from e

        # update brace/parentheses balance
        if tokens == TOKEN_OPERATOR:
            if data == "{":
                balancing_stack.append("}")
            elif data == "(":
                balancing_stack.append(")")
            elif data == "[":
                balancing_stack.append("]")
            elif data in ("}", ")", "]"):
                if not balancing_stack:
                    raise TemplateSyntaxError(
                        f"unexpected '{data}'", lineno, name, filename
                    )

                expected_op = balancing_stack.pop()

                if expected_op != data:
                    raise TemplateSyntaxError(
                        f"unexpected '{data}', expected '{expected_op}'",
                        lineno,
                        name,
                        filename,
                    )

        # yield items
        if data or tokens not in ignore_if_empty:
            yield lineno, tokens, data

        lineno += data.count("\n")

    line_starting = m.group()[-1:] == "\n"
    # fetch new position into new variable so that we can check
    # if there is a internal parsing error which would result
    # in an infinite loop
    pos2 = m.end()

    # handle state changes
    if new_state is not None:
        # remove the uppermost state
        if new_state == "#pop":
            stack.pop()
        # resolve the new state by group checking
        elif new_state == "#bygroup":
            for key, value in m.groupdict().items():
                if value is not None:
                    stack.append(key)
                    break
            else:
                raise RuntimeError(
                    f"{regex!r} wanted to resolve the new state dynamically"
                    f" but no group matched"
                )
        # direct state name given
        else:
            stack.append(new_state)

        statetokens = self.rules[stack[-1]]
    # we are still at the same position and no stack change.
    # this means a loop without break condition, avoid that and
    # raise error
    elif pos2 == pos:
        raise RuntimeError(
            f"{regex!r} yielded empty string without stack change"
        )

    # publish new function and start again
    pos = pos2
    break
# if loop terminated without break we haven't found a single match
# either we are at the end of the file or we have a problem
else:
    # end of text
    if pos >= source_length:
        return

    # something went wrong
    raise TemplateSyntaxError(
        f"unexpected char {source[pos]!r} at {pos}", lineno, name, filename
    )

def super(
    self, name: str, current: t.Callable[["Context"], t.Iterator[str]]
) -> t.Union["BlockReference", "Undefined"]:
    """Render a parent block."""
    try:
        blocks = self.blocks[name]
        index = blocks.index(current) + 1
        blocks[index]
    except LookupError:
        return self.environment.undefined(
            f"there is no parent block called {name!r}.", name="super"
        )
    return BlockReference(name, self, blocks, index)

def visit_FromImport(self, node: nodes.FromImport, frame: Frame) -> None:
    """Visit named imports."""
    self.newline(node)
    self.write("included_template = ")
    self._import_common(node, frame)
    var_names = []
    discarded_names = []
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        self.writeline(
            f"{frame.symbols.ref(alias)} ="
            f" getattr(included_template, {name!r}, missing)"
        )
        self.writeline(f"if {frame.symbols.ref(alias)} is missing:")
        self.indent()
        # The position will contain the template name, and will be formatted
        # into a string that will be compiled into an f-string. Curly braces
        # in the name must be replaced with escapes so that they will not be
        # executed as part of the f-string.
        position = self.position(node).replace("{", "{{").replace("}", "}}")
        message = (
            "the template {included_template.__name__!r}"
            f" (imported on {position})"
            f" does not export the requested name {name!r}"
        )
        self.writeline(
            f"{frame.symbols.ref(alias)} = undefined(f{message!r}, name={name!r})"
        )
        self.outdent()
        if frame.toplevel:
            var_names.append(alias)
            if not alias.startswith("_"):
                discarded_names.append(alias)

    if var_names:
        if len(var_names) == 1:
            name = var_names[0]
            self.writeline(f"context.vars[{name!r}] = {frame.symbols.ref(name)}")
        else:
            names_kv = ", ".join(
                f"{name!r}: {frame.symbols.ref(name)}" for name in var_names
            )
            self.writeline(f"context.vars.update({{{names_kv}}})")
    if discarded_names:
        if len(discarded_names) == 1:
            self.writeline(f"context.exported_vars.discard({discarded_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, discarded_names))
            self.writeline(
                f"context.exported_vars.difference_update(({names_str}))"
            )

def __getitem__(self, name: str) -> t.Any:
    blocks = self.__context.blocks[name]
    return BlockReference(name, self.__context, blocks, 0)

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

