def split_template_path(template: str) -> t.List[str]:
    """Split a path into segments and perform a sanity check.  If it detects
    '..' in the path it will raise a `TemplateNotFound` error.
    """
    pieces = []
    for piece in template.split("/"):
        if (
            os.path.sep in piece
            or (os.path.altsep and os.path.altsep in piece)
            or piece == os.path.pardir
        ):
            raise TemplateNotFound(template)
        elif piece and piece != ".":
            pieces.append(piece)
    return pieces

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, str, t.Callable[[], bool]]:
    pieces = split_template_path(template)

    for searchpath in self.searchpath:
        # Use posixpath even on Windows to avoid "drive:" or UNC
        # segments breaking out of the search directory.
        filename = posixpath.join(searchpath, *pieces)

        if os.path.isfile(filename):
            break
    else:
        plural = "path" if len(self.searchpath) == 1 else "paths"
        paths_str = ", ".join(repr(p) for p in self.searchpath)
        raise TemplateNotFound(
            template,
            f"{template!r} not found in search {plural}: {paths_str}",
        )

    with open(filename, encoding=self.encoding) as f:
        contents = f.read()

    mtime = os.path.getmtime(filename)

    def uptodate() -> bool:
        try:
            return os.path.getmtime(filename) == mtime
        except OSError:
            return False

    # Use normpath to convert Windows altsep to sep.
    return contents, os.path.normpath(filename), uptodate

def list_templates(self) -> t.List[str]:
    found = set()
    for searchpath in self.searchpath:
        walk_dir = os.walk(searchpath, followlinks=self.followlinks)
        for dirpath, _, filenames in walk_dir:
            for filename in filenames:
                template = (
                    os.path.join(dirpath, filename)[len(searchpath) :]
                    .strip(os.path.sep)
                    .replace(os.path.sep, "/")
                )
                if template[:2] == "./":
                    template = template[2:]
                if template not in found:
                    found.add(template)
    return sorted(found)

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, str, t.Optional[t.Callable[[], bool]]]:
    # Use posixpath even on Windows to avoid "drive:" or UNC
    # segments breaking out of the search directory. Use normpath to
    # convert Windows altsep to sep.
    p = os.path.normpath(
        posixpath.join(self._template_root, *split_template_path(template))
    )
    up_to_date: t.Optional[t.Callable[[], bool]]

    if self._archive is None:
        # Package is a directory.
        if not os.path.isfile(p):
            raise TemplateNotFound(template)

        with open(p, "rb") as f:
            source = f.read()

        mtime = os.path.getmtime(p)

        def up_to_date() -> bool:
            return os.path.isfile(p) and os.path.getmtime(p) == mtime

    else:
        # Package is a zip file.
        try:
            source = self._loader.get_data(p)  # type: ignore
        except OSError as e:
            raise TemplateNotFound(template) from e

        # Could use the zip's mtime for all template mtimes, but
        # would need to safely reload the module if it's out of
        # date, so just report it as always current.
        up_to_date = None

    return source.decode(self.encoding), p, up_to_date

def get_loader(self, template: str) -> t.Tuple[BaseLoader, str]:
    try:
        prefix, name = template.split(self.delimiter, 1)
        loader = self.mapping[prefix]
    except (ValueError, KeyError) as e:
        raise TemplateNotFound(template) from e
    return loader, name

def list_templates(self) -> t.List[str]:
    results: t.List[str] = []

    if self._archive is None:
        # Package is a directory.
        offset = len(self._template_root)

        for dirpath, _, filenames in os.walk(self._template_root):
            dirpath = dirpath[offset:].lstrip(os.path.sep)
            results.extend(
                os.path.join(dirpath, name).replace(os.path.sep, "/")
                for name in filenames
            )
    else:
        files = _get_zipimporter_files(self._loader)

        # Package is a zip file.
        prefix = (
            self._template_root[len(self._archive) :].lstrip(os.path.sep)
            + os.path.sep
        )
        offset = len(prefix)

        for name in files:
            # Find names under the templates directory that aren't directories.
            if name.startswith(prefix) and name[-1] != os.path.sep:
                results.append(name[offset:].replace(os.path.sep, "/"))

    results.sort()
    return results

@staticmethod
def get_template_key(name: str) -> str:
    return "tmpl_" + sha1(name.encode("utf-8")).hexdigest()

@internalcode
def parse(
    self,
    source: str,
    name: t.Optional[str] = None,
    filename: t.Optional[str] = None,
) -> nodes.Template:
    """Parse the sourcecode and return the abstract syntax tree.  This
    tree of nodes is used by the compiler to convert the template into
    executable source- or bytecode.  This is useful for debugging or to
    extract information from templates.

    If you are :ref:`developing Jinja extensions <writing-extensions>`
    this gives you a good overview of the node tree generated.
    """
    try:
        return self._parse(source, name, filename)
    except TemplateSyntaxError:
        self.handle_exception(source=source)

def find_referenced_templates(ast: nodes.Template) -> t.Iterator[t.Optional[str]]:
    """Finds all the referenced templates from the AST.  This will return an
    iterator over all the hardcoded template extensions, inclusions and
    imports.  If dynamic inheritance or inclusion is used, `None` will be
    yielded.

    >>> from jinja2 import Environment, meta
    >>> env = Environment()
    >>> ast = env.parse('{% extends "layout.html" %}{% include helper %}')
    >>> list(meta.find_referenced_templates(ast))
    ['layout.html', None]

    This function is useful for dependency tracking.  For example if you want
    to rebuild parts of the website after a layout template has changed.
    """
    template_name: t.Any

    for node in ast.find_all(_ref_types):
        template: nodes.Expr = node.template  # type: ignore

        if not isinstance(template, nodes.Const):
            # a tuple with some non consts in there
            if isinstance(template, (nodes.Tuple, nodes.List)):
                for template_name in template.items:
                    # something const, only yield the strings and ignore
                    # non-string consts that really just make no sense
                    if isinstance(template_name, nodes.Const):
                        if isinstance(template_name.value, str):
                            yield template_name.value
                    # something dynamic in there
                    else:
                        yield None
            # something dynamic we don't know about here
            else:
                yield None
            continue
        # constant is a basestring, direct template name
        if isinstance(template.value, str):
            yield template.value
        # a tuple or list (latter *should* not happen) made of consts,
        # yield the consts that are strings.  We could warn here for
        # non string values
        elif isinstance(node, nodes.Include) and isinstance(
            template.value, (tuple, list)
        ):
            for template_name in template.value:
                if isinstance(template_name, str):
                    yield template_name
        # something else we don't care about, we could warn here
        else:
            yield None

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    loader, name = self.get_loader(template)
    try:
        return loader.get_source(environment, name)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(template) from e

@staticmethod
def get_module_filename(name: str) -> str:
    return ModuleLoader.get_template_key(name) + ".py"

def _parse(
    self, source: str, name: t.Optional[str], filename: t.Optional[str]
) -> nodes.Template:
    """Internal parsing function used by `parse` and `compile`."""
    return Parser(self, source, name, filename).parse()

@internalcode
def load(
    self,
    environment: "Environment",
    name: str,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    loader, local_name = self.get_loader(name)
    try:
        return loader.load(environment, local_name, globals)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(name) from e

@internalcode
def get_or_select_template(
    self,
    template_name_or_list: t.Union[
        str, "Template", t.List[t.Union[str, "Template"]]
    ],
    parent: t.Optional[str] = None,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    """Use :meth:`select_template` if an iterable of template names
    is given, or :meth:`get_template` if one name is given.

    .. versionadded:: 2.3
    """
    if isinstance(template_name_or_list, (str, Undefined)):
        return self.get_template(template_name_or_list, parent, globals)
    elif isinstance(template_name_or_list, Template):
        return template_name_or_list
    return self.select_template(template_name_or_list, parent, globals)

def __call__(self) -> str:
    if not self.used:
        self.used = True
        return ""
    return self.sep

def list_templates(self) -> t.List[str]:
    result = []
    for prefix, loader in self.mapping.items():
        for template in loader.list_templates():
            result.append(prefix + self.delimiter + template)
    return result

def _prepare_attribute_parts(
    attr: t.Optional[t.Union[str, int]],
) -> t.List[t.Union[str, int]]:
    if attr is None:
        return []

    if isinstance(attr, str):
        return [int(x) if x.isdigit() else x for x in attr.split(".")]

    return [attr]

def __init__(self, template: Template, undefined_to_none: bool) -> None:
    self._template = template
    self._undefined_to_none = undefined_to_none

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> t.Dict[str, t.Any]:
    """Based on the runtime locals, get the context that would be
    available at that point in the template.
    """
    # Start with the current template context.
    ctx: t.Optional[Context] = real_locals.get("context")

    if ctx is not None:
        data: t.Dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: t.Dict[str, t.Tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def __init__(
    self,
    names: t.Sequence[t.Union[str, "Undefined"]] = (),
    message: t.Optional[str] = None,
) -> None:
    if message is None:
        from .runtime import Undefined

        parts = []

        for name in names:
            if isinstance(name, Undefined):
                parts.append(name._undefined_message)
            else:
                parts.append(name)

        parts_str = ", ".join(map(str, parts))
        message = f"none of the templates given were found: {parts_str}"

    super().__init__(names[-1] if names else None, message)
    self.templates = list(names)

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    rv = self.load_func(template)

    if rv is None:
        raise TemplateNotFound(template)

    if isinstance(rv, str):
        return rv, None, None

    return rv

def __init__(self, sep: str = ", ") -> None:
    self.sep = sep
    self.used = False

def parse_include(self) -> nodes.Include:
    node = nodes.Include(lineno=next(self.stream).lineno)
    node.template = self.parse_expression()
    if self.stream.current.test("name:ignore") and self.stream.look().test(
        "name:missing"
    ):
        node.ignore_missing = True
        self.stream.skip(2)
    else:
        node.ignore_missing = False
    return self.parse_import_context(node, True)

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, None, t.Callable[[], bool]]:
    if template in self.mapping:
        source = self.mapping[template]
        return source, None, lambda: source == self.mapping.get(template)
    raise TemplateNotFound(template)

def get_field(
    self, field_name: str, args: t.Sequence[t.Any], kwargs: t.Mapping[str, t.Any]
) -> t.Tuple[t.Any, str]:
    first, rest = formatter_field_name_split(field_name)
    obj = self.get_value(first, args, kwargs)
    for is_attr, i in rest:
        if is_attr:
            obj = self._env.getattr(obj, i)
        else:
            obj = self._env.getitem(obj, i)
    return obj, first

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    for loader in self.loaders:
        try:
            return loader.get_source(environment, template)
        except TemplateNotFound:
            pass
    raise TemplateNotFound(template)

def parse_from(self) -> nodes.FromImport:
    node = nodes.FromImport(lineno=next(self.stream).lineno)
    node.template = self.parse_expression()
    self.stream.expect("name:import")
    node.names = []

    def parse_context() -> bool:
        if self.stream.current.value in {
            "with",
            "without",
        } and self.stream.look().test("name:context"):
            node.with_context = next(self.stream).value == "with"
            self.stream.skip()
            return True
        return False

    while True:
        if node.names:
            self.stream.expect("comma")
        if self.stream.current.type == "name":
            if parse_context():
                break
            target = self.parse_assign_target(name_only=True)
            if target.name.startswith("_"):
                self.fail(
                    "names starting with an underline can not be imported",
                    target.lineno,
                    exc=TemplateAssertionError,
                )
            if self.stream.skip_if("name:as"):
                alias = self.parse_assign_target(name_only=True)
                node.names.append((target.name, alias.name))
            else:
                node.names.append(target.name)
            if parse_context() or self.stream.current.type != "comma":
                break
        else:
            self.stream.expect("name")
    if not hasattr(node, "with_context"):
        node.with_context = False
    return node

def parse_filter(
    self, node: t.Optional[nodes.Expr], start_inline: bool = False
) -> t.Optional[nodes.Expr]:
    while self.stream.current.type == "pipe" or start_inline:
        if not start_inline:
            next(self.stream)
        token = self.stream.expect("name")
        name = token.value
        while self.stream.current.type == "dot":
            next(self.stream)
            name += "." + self.stream.expect("name").value
        if self.stream.current.type == "lparen":
            args, kwargs, dyn_args, dyn_kwargs = self.parse_call_args()
        else:
            args = []
            kwargs = []
            dyn_args = dyn_kwargs = None
        node = nodes.Filter(
            node, name, args, kwargs, dyn_args, dyn_kwargs, lineno=token.lineno
        )
        start_inline = False
    return node

def subparse(
    self, end_tokens: t.Optional[t.Tuple[str, ...]] = None
) -> t.List[nodes.Node]:
    body: t.List[nodes.Node] = []
    data_buffer: t.List[nodes.Node] = []
    add_data = data_buffer.append

    if end_tokens is not None:
        self._end_token_stack.append(end_tokens)

    def flush_data() -> None:
        if data_buffer:
            lineno = data_buffer[0].lineno
            body.append(nodes.Output(data_buffer[:], lineno=lineno))
            del data_buffer[:]

    try:
        while self.stream:
            token = self.stream.current
            if token.type == "data":
                if token.value:
                    add_data(nodes.TemplateData(token.value, lineno=token.lineno))
                next(self.stream)
            elif token.type == "variable_begin":
                next(self.stream)
                add_data(self.parse_tuple(with_condexpr=True))
                self.stream.expect("variable_end")
            elif token.type == "block_begin":
                flush_data()
                next(self.stream)
                if end_tokens is not None and self.stream.current.test_any(
                    *end_tokens
                ):
                    return body
                rv = self.parse_statement()
                if isinstance(rv, list):
                    body.extend(rv)
                else:
                    body.append(rv)
                self.stream.expect("block_end")
            else:
                raise AssertionError("internal parsing error")

        flush_data()
    finally:
        if end_tokens is not None:
            self._end_token_stack.pop()
    return body

def parse(self, parser: "Parser") -> t.Union[nodes.Node, t.List[nodes.Node]]:
    """Parse a translatable tag."""
    lineno = next(parser.stream).lineno

    context = None
    context_token = parser.stream.next_if("string")

    if context_token is not None:
        context = context_token.value

    # find all the variables referenced.  Additionally a variable can be
    # defined in the body of the trans block too, but this is checked at
    # a later state.
    plural_expr: t.Optional[nodes.Expr] = None
    plural_expr_assignment: t.Optional[nodes.Assign] = None
    num_called_num = False
    variables: t.Dict[str, nodes.Expr] = {}
    trimmed = None
    while parser.stream.current.type != "block_end":
        if variables:
            parser.stream.expect("comma")

        # skip colon for python compatibility
        if parser.stream.skip_if("colon"):
            break

        token = parser.stream.expect("name")
        if token.value in variables:
            parser.fail(
                f"translatable variable {token.value!r} defined twice.",
                token.lineno,
                exc=TemplateAssertionError,
            )

        # expressions
        if parser.stream.current.type == "assign":
            next(parser.stream)
            variables[token.value] = var = parser.parse_expression()
        elif trimmed is None and token.value in ("trimmed", "notrimmed"):
            trimmed = token.value == "trimmed"
            continue
        else:
            variables[token.value] = var = nodes.Name(token.value, "load")

        if plural_expr is None:
            if isinstance(var, nodes.Call):
                plural_expr = nodes.Name("_trans", "load")
                variables[token.value] = plural_expr
                plural_expr_assignment = nodes.Assign(
                    nodes.Name("_trans", "store"), var
                )
            else:
                plural_expr = var
            num_called_num = token.value == "num"

    parser.stream.expect("block_end")

    plural = None
    have_plural = False
    referenced = set()

    # now parse until endtrans or pluralize
    singular_names, singular = self._parse_block(parser, True)
    if singular_names:
        referenced.update(singular_names)
        if plural_expr is None:
            plural_expr = nodes.Name(singular_names[0], "load")
            num_called_num = singular_names[0] == "num"

    # if we have a pluralize block, we parse that too
    if parser.stream.current.test("name:pluralize"):
        have_plural = True
        next(parser.stream)
        if parser.stream.current.type != "block_end":
            token = parser.stream.expect("name")
            if token.value not in variables:
                parser.fail(
                    f"unknown variable {token.value!r} for pluralization",
                    token.lineno,
                    exc=TemplateAssertionError,
                )
            plural_expr = variables[token.value]
            num_called_num = token.value == "num"
        parser.stream.expect("block_end")
        plural_names, plural = self._parse_block(parser, False)
        next(parser.stream)
        referenced.update(plural_names)
    else:
        next(parser.stream)

    # register free names as simple name expressions
    for name in referenced:
        if name not in variables:
            variables[name] = nodes.Name(name, "load")

    if not have_plural:
        plural_expr = None
    elif plural_expr is None:
        parser.fail("pluralize without variables", lineno)

    if trimmed is None:
        trimmed = self.environment.policies["ext.i18n.trimmed"]
    if trimmed:
        singular = self._trim_whitespace(singular)
        if plural:
            plural = self._trim_whitespace(plural)

    node = self._make_node(
        singular,
        plural,
        context,
        variables,
        plural_expr,
        bool(referenced),
        num_called_num and have_plural,
    )
    node.set_lineno(lineno)
    if plural_expr_assignment is not None:
        return [plural_expr_assignment, node]
    else:
        return node

def visit_FromImport(self, node: nodes.FromImport, frame: Frame) -> None:
    """Visit named imports."""
    self.newline(node)
    self.write("included_template = ")
    self._import_common(node, frame)
    var_names = []
    discarded_names = []
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        self.writeline(
            f"{frame.symbols.ref(alias)} ="
            f" getattr(included_template, {name!r}, missing)"
        )
        self.writeline(f"if {frame.symbols.ref(alias)} is missing:")
        self.indent()
        # The position will contain the template name, and will be formatted
        # into a string that will be compiled into an f-string. Curly braces
        # in the name must be replaced with escapes so that they will not be
        # executed as part of the f-string.
        position = self.position(node).replace("{", "{{").replace("}", "}}")
        message = (
            "the template {included_template.__name__!r}"
            f" (imported on {position})"
            f" does not export the requested name {name!r}"
        )
        self.writeline(
            f"{frame.symbols.ref(alias)} = undefined(f{message!r}, name={name!r})"
        )
        self.outdent()
        if frame.toplevel:
            var_names.append(alias)
            if not alias.startswith("_"):
                discarded_names.append(alias)

    if var_names:
        if len(var_names) == 1:
            name = var_names[0]
            self.writeline(f"context.vars[{name!r}] = {frame.symbols.ref(name)}")
        else:
            names_kv = ", ".join(
                f"{name!r}: {frame.symbols.ref(name)}" for name in var_names
            )
            self.writeline(f"context.vars.update({{{names_kv}}})")
    if discarded_names:
        if len(discarded_names) == 1:
            self.writeline(f"context.exported_vars.discard({discarded_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, discarded_names))
            self.writeline(
                f"context.exported_vars.difference_update(({names_str}))"
            )

