        # Could use the zip's mtime for all template mtimes, but
        # would need to safely reload the module if it's out of
        # date, so just report it as always current.
        up_to_date = None

    return source.decode(self.encoding), p, up_to_date

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, str, t.Callable[[], bool]]:
    pieces = split_template_path(template)

    for searchpath in self.searchpath:
        # Use posixpath even on Windows to avoid "drive:" or UNC
        # segments breaking out of the search directory.
        filename = posixpath.join(searchpath, *pieces)

        if os.path.isfile(filename):
            break
    else:
        plural = "path" if len(self.searchpath) == 1 else "paths"
        paths_str = ", ".join(repr(p) for p in self.searchpath)
        raise TemplateNotFound(
            template,
            f"{template!r} not found in search {plural}: {paths_str}",
        )

    with open(filename, encoding=self.encoding) as f:
        contents = f.read()

    mtime = os.path.getmtime(filename)

    def uptodate() -> bool:
        try:
            return os.path.getmtime(filename) == mtime
        except OSError:
            return False

    # Use normpath to convert Windows altsep to sep.
    return contents, os.path.normpath(filename), uptodate

def list_templates(self) -> t.List[str]:
    results: t.List[str] = []

    if self._archive is None:
        # Package is a directory.
        offset = len(self._template_root)

        for dirpath, _, filenames in os.walk(self._template_root):
            dirpath = dirpath[offset:].lstrip(os.path.sep)
            results.extend(
                os.path.join(dirpath, name).replace(os.path.sep, "/")
                for name in filenames
            )
    else:
        files = _get_zipimporter_files(self._loader)

        # Package is a zip file.
        prefix = (
            self._template_root[len(self._archive) :].lstrip(os.path.sep)
            + os.path.sep
        )
        offset = len(prefix)

        for name in files:
            # Find names under the templates directory that aren't directories.
            if name.startswith(prefix) and name[-1] != os.path.sep:
                results.append(name[offset:].replace(os.path.sep, "/"))

    results.sort()
    return results

@internalcode
def parse(
    self,
    source: str,
    name: t.Optional[str] = None,
    filename: t.Optional[str] = None,
) -> nodes.Template:
    """Parse the sourcecode and return the abstract syntax tree.  This
    tree of nodes is used by the compiler to convert the template into
    executable source- or bytecode.  This is useful for debugging or to
    extract information from templates.

    If you are :ref:`developing Jinja extensions <writing-extensions>`
    this gives you a good overview of the node tree generated.
    """
    try:
        return self._parse(source, name, filename)
    except TemplateSyntaxError:
        self.handle_exception(source=source)

@internalcode
def get_or_select_template(
    self,
    template_name_or_list: t.Union[
        str, "Template", t.List[t.Union[str, "Template"]]
    ],
    parent: t.Optional[str] = None,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    """Use :meth:`select_template` if an iterable of template names
    is given, or :meth:`get_template` if one name is given.

    .. versionadded:: 2.3
    """
    if isinstance(template_name_or_list, (str, Undefined)):
        return self.get_template(template_name_or_list, parent, globals)
    elif isinstance(template_name_or_list, Template):
        return template_name_or_list
    return self.select_template(template_name_or_list, parent, globals)

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> t.Dict[str, t.Any]:
    """Based on the runtime locals, get the context that would be
    available at that point in the template.
    """
    # Start with the current template context.
    ctx: t.Optional[Context] = real_locals.get("context")

    if ctx is not None:
        data: t.Dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: t.Dict[str, t.Tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def parse_filter(
    self, node: t.Optional[nodes.Expr], start_inline: bool = False
) -> t.Optional[nodes.Expr]:
    while self.stream.current.type == "pipe" or start_inline:
        if not start_inline:
            next(self.stream)
        token = self.stream.expect("name")
        name = token.value
        while self.stream.current.type == "dot":
            next(self.stream)
            name += "." + self.stream.expect("name").value
        if self.stream.current.type == "lparen":
            args, kwargs, dyn_args, dyn_kwargs = self.parse_call_args()
        else:
            args = []
            kwargs = []
            dyn_args = dyn_kwargs = None
        node = nodes.Filter(
            node, name, args, kwargs, dyn_args, dyn_kwargs, lineno=token.lineno
        )
        start_inline = False
    return node

def list_templates(self) -> t.List[str]:
    found = set()
    for searchpath in self.searchpath:
        walk_dir = os.walk(searchpath, followlinks=self.followlinks)
        for dirpath, _, filenames in walk_dir:
            for filename in filenames:
                template = (
                    os.path.join(dirpath, filename)[len(searchpath) :]
                    .strip(os.path.sep)
                    .replace(os.path.sep, "/")
                )
                if template[:2] == "./":
                    template = template[2:]
                if template not in found:
                    found.add(template)
    return sorted(found)

def get_loader(self, template: str) -> t.Tuple[BaseLoader, str]:
    try:
        prefix, name = template.split(self.delimiter, 1)
        loader = self.mapping[prefix]
    except (ValueError, KeyError) as e:
        raise TemplateNotFound(template) from e
    return loader, name

def parse_tuple(
    self,
    simplified: bool = False,
    with_condexpr: bool = True,
    extra_end_rules: t.Optional[t.Tuple[str, ...]] = None,
    explicit_parentheses: bool = False,
    with_namespace: bool = False,
) -> t.Union[nodes.Tuple, nodes.Expr]:
    """Works like `parse_expression` but if multiple expressions are
    delimited by a comma a :class:`~jinja2.nodes.Tuple` node is created.
    This method could also return a regular expression instead of a tuple
    if no commas where found.

    The default parsing mode is a full tuple.  If `simplified` is `True`
    only names and literals are parsed; ``with_namespace`` allows namespace
    attr refs as well. The `no_condexpr` parameter is forwarded to
    :meth:`parse_expression`.

    Because tuples do not require delimiters and may end in a bogus comma
    an extra hint is needed that marks the end of a tuple.  For example
    for loops support tuples between `for` and `in`.  In that case the
    `extra_end_rules` is set to ``['name:in']``.

    `explicit_parentheses` is true if the parsing was triggered by an
    expression in parentheses.  This is used to figure out if an empty
    tuple is a valid expression or not.
    """
    lineno = self.stream.current.lineno
    if simplified:

        def parse() -> nodes.Expr:
            return self.parse_primary(with_namespace=with_namespace)

    else:

        def parse() -> nodes.Expr:
            return self.parse_expression(with_condexpr=with_condexpr)

    args: t.List[nodes.Expr] = []
    is_tuple = False

    while True:
        if args:
            self.stream.expect("comma")
        if self.is_tuple_end(extra_end_rules):
            break
        args.append(parse())
        if self.stream.current.type == "comma":
            is_tuple = True
        else:
            break
        lineno = self.stream.current.lineno

    if not is_tuple:
        if args:
            return args[0]

        # if we don't have explicit parentheses, an empty tuple is
        # not a valid expression.  This would mean nothing (literally
        # nothing) in the spot of an expression would be an empty
        # tuple.
        if not explicit_parentheses:
            self.fail(
                "Expected an expression,"
                f" got {describe_token(self.stream.current)!r}"
            )

    return nodes.Tuple(args, "load", lineno=lineno)

@staticmethod
def get_template_key(name: str) -> str:
    return "tmpl_" + sha1(name.encode("utf-8")).hexdigest()

@internalcode
def _get_default_module(self, ctx: t.Optional[Context] = None) -> "TemplateModule":
    """If a context is passed in, this means that the template was
    imported. Imported templates have access to the current
    template's globals by default, but they can only be accessed via
    the context during runtime.

    If there are new globals, we need to create a new module because
    the cached module is already rendered and will not have access
    to globals from the current context. This new module is not
    cached because the template can be imported elsewhere, and it
    should have access to only the current template's globals.
    """
    if self.environment.is_async:
        raise RuntimeError("Module is not available in async mode.")

    if ctx is not None:
        keys = ctx.globals_keys - self.globals.keys()

        if keys:
            return self.make_module({k: ctx.parent[k] for k in keys})

    if self._module is None:
        self._module = self.make_module()

    return self._module

def find_referenced_templates(ast: nodes.Template) -> t.Iterator[t.Optional[str]]:
    """Finds all the referenced templates from the AST.  This will return an
    iterator over all the hardcoded template extensions, inclusions and
    imports.  If dynamic inheritance or inclusion is used, `None` will be
    yielded.

    >>> from jinja2 import Environment, meta
    >>> env = Environment()
    >>> ast = env.parse('{% extends "layout.html" %}{% include helper %}')
    >>> list(meta.find_referenced_templates(ast))
    ['layout.html', None]

    This function is useful for dependency tracking.  For example if you want
    to rebuild parts of the website after a layout template has changed.
    """
    template_name: t.Any

    for node in ast.find_all(_ref_types):
        template: nodes.Expr = node.template  # type: ignore

        if not isinstance(template, nodes.Const):
            # a tuple with some non consts in there
            if isinstance(template, (nodes.Tuple, nodes.List)):
                for template_name in template.items:
                    # something const, only yield the strings and ignore
                    # non-string consts that really just make no sense
                    if isinstance(template_name, nodes.Const):
                        if isinstance(template_name.value, str):
                            yield template_name.value
                    # something dynamic in there
                    else:
                        yield None
            # something dynamic we don't know about here
            else:
                yield None
            continue
        # constant is a basestring, direct template name
        if isinstance(template.value, str):
            yield template.value
        # a tuple or list (latter *should* not happen) made of consts,
        # yield the consts that are strings.  We could warn here for
        # non string values
        elif isinstance(node, nodes.Include) and isinstance(
            template.value, (tuple, list)
        ):
            for template_name in template.value:
                if isinstance(template_name, str):
                    yield template_name
        # something else we don't care about, we could warn here
        else:
            yield None

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    loader, name = self.get_loader(template)
    try:
        return loader.get_source(environment, name)
    except TemplateNotFound as e:
        # re-raise the exception with the correct filename here.
        # (the one that includes the prefix)
        raise TemplateNotFound(template) from e

@staticmethod
def get_module_filename(name: str) -> str:
    return ModuleLoader.get_template_key(name) + ".py"

def parse_postfix(self, node: nodes.Expr) -> nodes.Expr:
    while True:
        token_type = self.stream.current.type
        if token_type == "dot" or token_type == "lbracket":
            node = self.parse_subscript(node)
        # calls are valid both after postfix expressions (getattr
        # and getitem) as well as filters and tests
        elif token_type == "lparen":
            node = self.parse_call(node)
        else:
            break
    return node

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

def clear(self) -> None:
    # imported lazily here because google app-engine doesn't support
    # write access on the file system and the function does not exist
    # normally.
    from os import remove

    files = fnmatch.filter(os.listdir(self.directory), self.pattern % ("*",))
    for filename in files:
        try:
            remove(os.path.join(self.directory, filename))
        except OSError:
            pass

def _parse(
