def _render_parts(
    self,
    header_parts: (
        dict[str, _TYPE_FIELD_VALUE | None]
        | typing.Sequence[tuple[str, _TYPE_FIELD_VALUE | None]]
    ),
) -> str:
    """
    Helper function to format and quote a single header.

    Useful for single headers that are composed of multiple items. E.g.,
    'Content-Disposition' fields.

    :param header_parts:
        A sequence of (k, v) tuples or a :class:`dict` of (k, v) to format
        as `k1="v1"; k2="v2"; ...`.
    """
    iterable: typing.Iterable[tuple[str, _TYPE_FIELD_VALUE | None]]

    parts = []
    if isinstance(header_parts, dict):
        iterable = header_parts.items()
    else:
        iterable = header_parts

    for name, value in iterable:
        if value is not None:
            parts.append(self._render_part(name, value))

    return "; ".join(parts)

def render_headers(self) -> str:
    """
    Renders the headers for this request field.
    """
    lines = []

    sort_keys = ["Content-Disposition", "Content-Type", "Content-Location"]
    for sort_key in sort_keys:
        if self.headers.get(sort_key, False):
            lines.append(f"{sort_key}: {self.headers[sort_key]}")

    for header_name, header_value in self.headers.items():
        if header_name not in sort_keys:
            if header_value:
                lines.append(f"{header_name}: {header_value}")

    lines.append("\r\n")
    return "\r\n".join(lines)

def extend(self, *args: ValidHTTPHeaderSource, **kwargs: str) -> None:
    """Generic import function for any type of header-like object.
    Adapted version of MutableMapping.update in order to insert items
    with self.add instead of self.__setitem__
    """
    if len(args) > 1:
        raise TypeError(
            f"extend() takes at most 1 positional arguments ({len(args)} given)"
        )
    other = args[0] if len(args) >= 1 else ()

    if isinstance(other, HTTPHeaderDict):
        for key, val in other.iteritems():
            self.add(key, val)
    elif isinstance(other, typing.Mapping):
        for key, val in other.items():
            self.add(key, val)
    elif isinstance(other, typing.Iterable):
        other = typing.cast(typing.Iterable[tuple[str, str]], other)
        for key, value in other:
            self.add(key, value)
    elif hasattr(other, "keys") and hasattr(other, "__getitem__"):
        # THIS IS NOT A TYPESAFE BRANCH
        # In this branch, the object has a `keys` attr but is not a Mapping or any of
        # the other types indicated in the method signature. We do some stuff with
        # it as though it partially implements the Mapping interface, but we're not
        # doing that stuff safely AT ALL.
        for key in other.keys():
            self.add(key, other[key])

    for key, value in kwargs.items():
        self.add(key, value)

def __iter__(self) -> typing.Iterator[str]:
    # Only provide the originally cased names
    for vals in self._container.values():
        yield vals[0]

def ensure_can_construct_http_header_dict(
    potential: object,
) -> ValidHTTPHeaderSource | None:
    if isinstance(potential, HTTPHeaderDict):
        return potential
    elif isinstance(potential, typing.Mapping):
        # Full runtime checking of the contents of a Mapping is expensive, so for the
        # purposes of typechecking, we assume that any Mapping is the right shape.
        return typing.cast(typing.Mapping[str, str], potential)
    elif isinstance(potential, typing.Iterable):
        # Similarly to Mapping, full runtime checking of the contents of an Iterable is
        # expensive, so for the purposes of typechecking, we assume that any Iterable
        # is the right shape.
        return typing.cast(typing.Iterable[tuple[str, str]], potential)
    elif hasattr(potential, "keys") and hasattr(potential, "__getitem__"):
        return typing.cast("HasGettableStringKeys", potential)
    else:
        return None

def _remove_path_dot_segments(path: str) -> str:
    # See http://tools.ietf.org/html/rfc3986#section-5.2.4 for pseudo-code
    segments = path.split("/")  # Turn the path into a list of segments
    output = []  # Initialize the variable to use to store output

    for segment in segments:
        # '.' is the current directory, so ignore it, it is superfluous
        if segment == ".":
            continue
        # Anything other than '..', should be appended to the output
        if segment != "..":
            output.append(segment)
        # In this case segment == '..', if we can, we should pop the last
        # element
        elif output:
            output.pop()

    # If the path starts with '/' and the output is empty or the first string
    # is non-empty
    if path.startswith("/") and (not output or output[0]):
        output.insert(0, "")

    # If the path starts with '/.' or '/..' ensure we add one more empty
    # string to add a trailing '/'
    if path.endswith(("/.", "/..")):
        output.append("")

    return "/".join(output)

def itermerged(self) -> typing.Iterator[tuple[str, str]]:
    """Iterate over all headers, merging duplicate ones together."""
    for key in self:
        val = self._container[key.lower()]
        yield val[0], ", ".join(val[1:])

def match_hostname(
    cert: _TYPE_PEER_CERT_RET_DICT | None,
    hostname: str,
    hostname_checks_common_name: bool = False,
) -> None:
    """Verify that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125
    rules are followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing.
    """
    if not cert:
        raise ValueError(
            "empty or no certificate, match_hostname needs a "
            "SSL socket or SSL context with either "
            "CERT_OPTIONAL or CERT_REQUIRED"
        )
    try:
        # Divergence from upstream: ipaddress can't handle byte str
        #
        # The ipaddress module shipped with Python < 3.9 does not support
        # scoped IPv6 addresses so we unconditionally strip the Zone IDs for
        # now. Once we drop support for Python 3.9 we can remove this branch.
        if "%" in hostname:
            host_ip = ipaddress.ip_address(hostname[: hostname.rfind("%")])
        else:
            host_ip = ipaddress.ip_address(hostname)

    except ValueError:
        # Not an IP address (common case)
        host_ip = None
    dnsnames = []
    san: tuple[tuple[str, str], ...] = cert.get("subjectAltName", ())
    key: str
    value: str
    for key, value in san:
        if key == "DNS":
            if host_ip is None and _dnsname_match(value, hostname):
                return
            dnsnames.append(value)
        elif key == "IP Address":
            if host_ip is not None and _ipaddress_match(value, host_ip):
                return
            dnsnames.append(value)

    # We only check 'commonName' if it's enabled and we're not verifying
    # an IP address. IP addresses aren't valid within 'commonName'.
    if hostname_checks_common_name and host_ip is None and not dnsnames:
        for sub in cert.get("subject", ()):
            for key, value in sub:
                if key == "commonName":
                    if _dnsname_match(value, hostname):
                        return
                    dnsnames.append(value)  # Defensive: for Python < 3.9.3

    if len(dnsnames) > 1:
        raise CertificateError(
            "hostname %r "
            "doesn't match either of %s" % (hostname, ", ".join(map(repr, dnsnames)))
        )
    elif len(dnsnames) == 1:
        raise CertificateError(f"hostname {hostname!r} doesn't match {dnsnames[0]!r}")
    else:
        raise CertificateError("no appropriate subjectAltName fields were found")

def putheader(self, header: str, *values: str) -> None:  # type: ignore[override]
    """"""
    if not any(isinstance(v, str) and v == SKIP_HEADER for v in values):
        super().putheader(header, *values)
    elif to_str(header.lower()) not in SKIPPABLE_HEADERS:
        skippable_headers = "', '".join(
            [str.title(header) for header in sorted(SKIPPABLE_HEADERS)]
        )
        raise ValueError(
            f"urllib3.util.SKIP_HEADER only supports '{skippable_headers}'"
        )

def _has_value_for_header(self, header_name: str, potential_value: str) -> bool:
    if header_name in self:
        return potential_value in self._container[header_name.lower()][1:]
    return False

def __getitem__(self, key: str) -> str:
    val = self._container[key.lower()]
    return ", ".join(val[1:])

def _merge_pool_kwargs(
    self, override: dict[str, typing.Any] | None
) -> dict[str, typing.Any]:
    """
    Merge a dictionary of override values for self.connection_pool_kw.

    This does not modify self.connection_pool_kw and returns a new dict.
    Any keys in the override dictionary with a value of ``None`` are
    removed from the merged dictionary.
    """
    base_pool_kwargs = self.connection_pool_kw.copy()
    if override:
        for key, value in override.items():
            if value is None:
                try:
                    del base_pool_kwargs[key]
                except KeyError:
                    pass
            else:
                base_pool_kwargs[key] = value
    return base_pool_kwargs

def _copy_from(self, other: HTTPHeaderDict) -> None:
    for key in other:
        val = other.getlist(key)
        self._container[key.lower()] = [key, *val]

@classmethod
def _validate_timeout(cls, value: _TYPE_TIMEOUT, name: str) -> _TYPE_TIMEOUT:
    """Check that a timeout attribute is valid.

    :param value: The timeout value to validate
    :param name: The name of the timeout attribute to validate. This is
        used to specify in error messages.
    :return: The validated and casted version of the given value.
    :raises ValueError: If it is a numeric value less than or equal to
        zero, or the type is not an integer, float, or None.
    """
    if value is None or value is _DEFAULT_TIMEOUT:
        return value

    if isinstance(value, bool):
        raise ValueError(
            "Timeout cannot be a boolean value. It must "
            "be an int, float or None."
        )
    try:
        float(value)
    except (TypeError, ValueError):
        raise ValueError(
            "Timeout value %s was %s, but it must be an "
            "int, float or None." % (name, value)
        ) from None

    try:
        if value <= 0:
            raise ValueError(
                "Attempted to set %s timeout to %s, but the "
                "timeout cannot be set to a value less "
                "than or equal to 0." % (name, value)
            )
    except TypeError:
        raise ValueError(
            "Timeout value %s was %s, but it must be an "
            "int, float or None." % (name, value)
        ) from None

    return value

def iteritems(self) -> typing.Iterator[tuple[str, str]]:
    """Iterate over all header lines, including duplicate ones."""
    for key in self:
        vals = self._container[key.lower()]
        for val in vals[1:]:
            yield vals[0], val

def __setitem__(self, key: str, val: str) -> None:
    # avoid a bytes/str comparison by decoding before httplib
    if isinstance(key, bytes):
        key = key.decode("latin-1")
    self._container[key.lower()] = [key, val]

def __eq__(self, other: object) -> bool:
    maybe_constructable = ensure_can_construct_http_header_dict(other)
    if maybe_constructable is None:
        return False
    else:
        other_as_http_header_dict = type(self)(maybe_constructable)

    return {k.lower(): v for k, v in self.itermerged()} == {
        k.lower(): v for k, v in other_as_http_header_dict.itermerged()
    }

def body_to_chunks(
    body: typing.Any | None, method: str, blocksize: int
) -> ChunksAndContentLength:
    """Takes the HTTP request method, body, and blocksize and
    transforms them into an iterable of chunks to pass to
    socket.sendall() and an optional 'Content-Length' header.

    A 'Content-Length' of 'None' indicates the length of the body
    can't be determined so should use 'Transfer-Encoding: chunked'
    for framing instead.
    """

    chunks: typing.Iterable[bytes] | None
    content_length: int | None

    # No body, we need to make a recommendation on 'Content-Length'
    # based on whether that request method is expected to have
    # a body or not.
    if body is None:
        chunks = None
        if method.upper() not in _METHODS_NOT_EXPECTING_BODY:
            content_length = 0
        else:
            content_length = None

    # Bytes or strings become bytes
    elif isinstance(body, (str, bytes)):
        chunks = (to_bytes(body),)
        content_length = len(chunks[0])

    # File-like object, TODO: use seek() and tell() for length?
    elif hasattr(body, "read"):

        def chunk_readable() -> typing.Iterable[bytes]:
            nonlocal body, blocksize
            encode = isinstance(body, io.TextIOBase)
            while True:
                datablock = body.read(blocksize)
                if not datablock:
                    break
                if encode:
                    datablock = datablock.encode("utf-8")
                yield datablock

        chunks = chunk_readable()
        content_length = None

    # Otherwise we need to start checking via duck-typing.
    else:
        try:
            # Check if the body implements the buffer API.
            mv = memoryview(body)
        except TypeError:
            try:
                # Check if the body is an iterable
                chunks = iter(body)
                content_length = None
            except TypeError:
                raise TypeError(
                    f"'body' must be a bytes-like object, file-like "
                    f"object, or iterable. Instead was {body!r}"
                ) from None
        else:
            # Since it implements the buffer API can be passed directly to socket.sendall()
            chunks = (body,)
            content_length = mv.nbytes

    return ChunksAndContentLength(chunks=chunks, content_length=content_length)

def __contains__(self, item: object) -> bool:
    if isinstance(item, tuple) and len(item) == 2:
        passed_key, passed_val = item
        if isinstance(passed_key, str) and isinstance(passed_val, str):
            return self._headers._has_value_for_header(passed_key, passed_val)
    return False

def idna_encode(name: str) -> bytes | None:
    """
    Borrowed wholesale from the Python Cryptography Project. It turns out
    that we can't just safely call `idna.encode`: it can explode for
    wildcard names. This avoids that problem.
    """
    import idna

    try:
        for prefix in ["*.", "."]:
            if name.startswith(prefix):
                name = name[len(prefix) :]
                return prefix.encode("ascii") + idna.encode(name)
        return idna.encode(name)
    except idna.core.IDNAError:
        return None

def __init__(self, headers: ValidHTTPHeaderSource | None = None, **kwargs: str):
    super().__init__()
    self._container = {}  # 'dict' is insert-ordered
    if headers is not None:
        if isinstance(headers, HTTPHeaderDict):
            self._copy_from(headers)
        else:
            self.extend(headers)
    if kwargs:
        self.extend(kwargs)

