    buffer: list[bytes] = []
    for chunk in self.stream(decode_content=True):
        if b"\n" in chunk:
            chunks = chunk.split(b"\n")
            yield b"".join(buffer) + chunks[0] + b"\n"
            for x in chunks[1:-1]:
                yield x + b"\n"
            if chunks[-1]:
                buffer = [chunks[-1]]
            else:
                buffer = []
        else:
            buffer.append(chunk)
    if buffer:
        yield b"".join(buffer)

