    self._retries = retries

def wait_for_socket(
    sock: socket.socket,
    read: bool = False,
    write: bool = False,
    timeout: float | None = None,
) -> bool:
    # We delay choosing which implementation to use until the first time we're
    # called. We could do it at import time, but then we might make the wrong
    # decision if someone goes wild with monkeypatching select.poll after
    # we're imported.
    global wait_for_socket
    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, "select"):
        wait_for_socket = select_wait_for_socket
    return wait_for_socket(sock, read, write, timeout)

def wrap_socket(
    self,
    sock: socket_cls,
    server_side: bool = False,
    do_handshake_on_connect: bool = True,
    suppress_ragged_eofs: bool = True,
    server_hostname: bytes | str | None = None,
) -> WrappedSocket:
    cnx = OpenSSL.SSL.Connection(self._ctx, sock)

    # If server_hostname is an IP, don't use it for SNI, per RFC6066 Section 3
    if server_hostname and not util.ssl_.is_ipaddress(server_hostname):
        if isinstance(server_hostname, str):
            server_hostname = server_hostname.encode("utf-8")
        cnx.set_tlsext_host_name(server_hostname)

    cnx.set_connect_state()

    while True:
        try:
            cnx.do_handshake()
        except OpenSSL.SSL.WantReadError as e:
            if not util.wait_for_read(sock, sock.gettimeout()):
                raise timeout("select timed out") from e
            continue
        except OpenSSL.SSL.Error as e:
            raise ssl.SSLError(f"bad handshake: {e!r}") from e
        break

    return WrappedSocket(cnx, sock)

def getresponse(self) -> BaseHTTPResponse:
    if self._response is not None:
        return EmscriptenHttpResponseWrapper(
            internal_response=self._response,
            url=self._response.request.url,
            connection=self,
        )
    else:
        raise ResponseNotReady()

def flush(self) -> None:
    if (
        self._fp is not None
        and hasattr(self._fp, "flush")
        and not getattr(self._fp, "closed", False)
    ):
        return self._fp.flush()

def rewind_body(body: typing.IO[typing.AnyStr], body_pos: _TYPE_BODY_POSITION) -> None:
    """
    Attempt to rewind body to a certain position.
    Primarily used for request redirects and retries.

    :param body:
        File-like object that supports seek.

    :param int pos:
        Position to seek to in file.
    """
    body_seek = getattr(body, "seek", None)
    if body_seek is not None and isinstance(body_pos, int):
        try:
            body_seek(body_pos)
        except OSError as e:
            raise UnrewindableBodyError(
                "An error occurred when rewinding request body for redirect/retry."
            ) from e
    elif body_pos is _FAILEDTELL:
        raise UnrewindableBodyError(
            "Unable to record file position for rewinding "
            "request body during a redirect/retry."
        )
    else:
        raise ValueError(
            f"body_pos must be of type integer, instead it was {type(body_pos)}."
        )

def __iter__(self) -> typing.Iterator[bytes]:
    buffer: list[bytes] = []
    for chunk in self.stream(decode_content=True):
        if b"\n" in chunk:
            chunks = chunk.split(b"\n")
            yield b"".join(buffer) + chunks[0] + b"\n"
            for x in chunks[1:-1]:
                yield x + b"\n"
            if chunks[-1]:
                buffer = [chunks[-1]]
            else:
                buffer = []
        else:
            buffer.append(chunk)
    if buffer:
        yield b"".join(buffer)

def parse_retry_after(self, retry_after: str) -> float:
    seconds: float
    # Whitespace: https://tools.ietf.org/html/rfc7230#section-3.2.4
    if re.match(r"^\s*[0-9]+\s*$", retry_after):
        seconds = int(retry_after)
    else:
        retry_date_tuple = email.utils.parsedate_tz(retry_after)
        if retry_date_tuple is None:
            raise InvalidHeader(f"Invalid Retry-After header: {retry_after}")

        retry_date = email.utils.mktime_tz(retry_date_tuple)
        seconds = retry_date - time.time()

    seconds = max(seconds, 0)

    return seconds

function validateFallback(
  schema: schemas.$ZodType,
  value: unknown,
  _ctx?: schemas.ParseContext<errors.$ZodIssue>
): boolean {
  const ctx: schemas.ParseContextInternal = _ctx
    ? { ..._ctx, async: false, abortEarly: true }
    : { async: false, abortEarly: true };
  const fallbackRun = (schema._zod.bag as CompiledBag).fallbackRun;
  let result: unknown;
  if (fallbackRun) {
    // skip nested fast paths on the fallback, so user callbacks keep the at-most-twice bound
    (ctx as Record<symbol, unknown>)[COMPILE_FALLBACK] = true;
    result = fallbackRun({ value, issues: [] }, ctx);
  } else {
    result = schema._zod.run({ value, issues: [] }, ctx);
  }
  if (result instanceof Promise) {
    throw new core.$ZodAsyncError();
  }
  return (result as schemas.ParsePayload).issues.length === 0;
}

validateAsync(data, params) {
  return parse.validateAsync(this, data, params);
},

validate: (value: unknown) => {
  const ctx: ParseContextInternal = { async: false };
  try {
    const r = inst._zod.run({ value, issues: [] }, ctx);
    if (!(r instanceof Promise)) return toStandardResult(r, ctx);
  } catch (_) {}
  // async function so a synchronously throwing check rejects instead of escaping validate
  return validateAsync(inst, value);
},

async function validateAsync(inst: $ZodType, value: unknown) {
  const ctx: ParseContextInternal = { async: true };
  return toStandardResult((await inst._zod.run({ value, issues: [] }, ctx)) as ParsePayload, ctx);
}

function throwAsync(): never {
  throw new $ZodAsyncError();
}

export const validateAsync: $ValidateAsync = async (schema, value, _ctx) => {
  const ctx: schemas.ParseContextInternal = _ctx
    ? { ..._ctx, async: true, abortEarly: true }
    : { async: true, abortEarly: true };
  let result: unknown = schema._zod.run({ value, issues: [] }, ctx);
  if (result instanceof Promise) result = await result;
  return (result as schemas.ParsePayload).issues.length === 0;
};

asyncResult = (asyncResult ?? Promise.resolve()).then(async () => {
  await _;
  const nextLen = payload.issues.length;
  if (nextLen === currLen) return;
  util.attachSchema(payload.issues, currLen, inst);
  if (!isAborted) isAborted = util.aborted(payload, currLen);
});

export function explicitlyAborted(x: schemas.ParsePayload, startIndex = 0): boolean {
  if (x.aborted === true) return true;
  for (let i = startIndex; i < x.issues.length; i++) {
    if (x.issues[i]?.continue === false) {
      return true;
    }
  }
  return false;
}

constructor() {
  super(`Encountered Promise during synchronous parse. Use .parseAsync() instead.`);
}

constructor(message = "z.compile does not support async refinements, transforms, or checks") {
  super(message);
  this.name = "ZodCompileAsyncError";
}

const wrapped = (payload: ParsePayload, ctx: ParseContextInternal): util.MaybeAsync<ParsePayload> => {
  // The value is a placeholder a back-edge is still waiting on, so the cycle closes through this transform. Its output can't exist in time to bind.
  if (ctx.direction !== "backward" && isBackEdge(ctx, payload.value)) throw new $ZodCyclicError();
  return base(payload, ctx);
};

