      case "invalid_key":
        return `Bọtìnì aṣìṣe nínú ${issue.origin}`;

      case "invalid_union":
        return "Ìbáwọlé aṣìṣe";

      case "invalid_element":
        return `Iye aṣìṣe nínú ${issue.origin}`;

      default:
        return "Ìbáwọlé aṣìṣe";
    }
  };
};

