const guard = z
  .transform((value: unknown) => value)
  .check((payload) => {
    const items = payload.value;
    if (!Array.isArray(items)) return;
    if (guards.uniqueItems === true) {
      const firstSeen = new Map<string, number>();
      for (let i = 0; i < items.length; i++) {
        const key = canonicalKey(items[i], new Set());
        if (key === null) continue;
        const first = firstSeen.get(key);
        if (first === undefined) {
          firstSeen.set(key, i);
          continue;
        }
        payload.issues.push({
          code: "custom",
          message: `Array items must be unique: element at index ${i} duplicates the one at index ${first}`,
          input: items,
          path: [i],
          continue: true,
        });
      }
    }
    if (guards.containsSchema) {
      const minContains = guards.minContains ?? 1;
      // one past the ceiling already proves the failure, and nothing above it changes the verdict
      const ceiling = guards.maxContains !== undefined ? guards.maxContains + 1 : Number.POSITIVE_INFINITY;
      let matches = 0;
      for (const item of items) {
        if (guards.containsSchema.safeParse(item).success && ++matches >= ceiling) break;
      }
      if (matches < minContains) {
        // the scan ran to the end, so this count is exact
        payload.issues.push({
          code: "custom",
          message: `Array must contain at least ${minContains} matching ${plural(minContains)}; found ${matches}`,
          input: items,
          continue: true,
        });
      }
      if (guards.maxContains !== undefined && matches > guards.maxContains) {
        payload.issues.push({
          code: "custom",
          message: `Array must contain at most ${guards.maxContains} matching ${plural(guards.maxContains)}`,
          input: items,
          continue: true,
        });
      }
    }
  });

function runtimeCatch(innerSchema: SomeType, catchValue: () => unknown, value: unknown): unknown {
  const result = (innerSchema._zod.run as (p: ParsePayload, c: ParseContextInternal) => any)(
    { value, issues: [] },
    {} as ParseContextInternal
  );
  if (result && typeof (result as Promise<unknown>).then === "function") return INVALID;
  const r = result as { value: unknown; issues: any[] };
  if (r.issues.length === 0) return r.value;
  // Only reached for a catch value that ignores the parse context — codegen refuses the rest — so there are no issues to finalize and nothing here needs the caller's error map.
  return catchValue();
}

