              value: { _errors: [] },
              enumerable: true,
              writable: true,
              configurable: true,
            });
          }
          const node = curr[el];
          if (terminal) {
            node._errors.push(mapper(issue));
          }
          curr = node;
          i++;
        }
      }
    }
  }
};

