def convert(
    self,
    value: "t.Union[str, os.PathLike[str]]",
    param: t.Optional["Parameter"],
    ctx: t.Optional["Context"],
) -> "t.Union[str, bytes, os.PathLike[str]]":
    rv = value

    is_dash = self.file_okay and self.allow_dash and rv in (b"-", "-")

    if not is_dash:
        if self.resolve_path:
            # os.path.realpath doesn't resolve symlinks on Windows
            # until Python 3.8. Use pathlib for now.
            import pathlib

            rv = os.fsdecode(pathlib.Path(rv).resolve())

        try:
            st = os.stat(rv)
        except OSError:
            if not self.exists:
                return self.coerce_path_result(rv)
            self.fail(
                _("{name} {filename!r} does not exist.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if not self.file_okay and stat.S_ISREG(st.st_mode):
            self.fail(
                _("{name} {filename!r} is a file.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )
        if not self.dir_okay and stat.S_ISDIR(st.st_mode):
            self.fail(
                _("{name} {filename!r} is a directory.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.readable and not os.access(rv, os.R_OK):
            self.fail(
                _("{name} {filename!r} is not readable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.writable and not os.access(rv, os.W_OK):
            self.fail(
                _("{name} {filename!r} is not writable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.executable and not os.access(value, os.X_OK):
            self.fail(
                _("{name} {filename!r} is not executable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

    return self.coerce_path_result(rv)

def coerce_path_result(
    self, value: "t.Union[str, os.PathLike[str]]"
) -> "t.Union[str, bytes, os.PathLike[str]]":
    if self.type is not None and not isinstance(value, self.type):
        if self.type is str:
            return os.fsdecode(value)
        elif self.type is bytes:
            return os.fsencode(value)
        else:
            return t.cast("os.PathLike[str]", self.type(value))

    return value

def convert(
    self,
    value: t.Union[str, "os.PathLike[str]", t.IO[t.Any]],
    param: t.Optional["Parameter"],
    ctx: t.Optional["Context"],
) -> t.IO[t.Any]:
    if _is_file_like(value):
        return value

    value = t.cast("t.Union[str, os.PathLike[str]]", value)

    try:
        lazy = self.resolve_lazy_flag(value)

        if lazy:
            lf = LazyFile(
                value, self.mode, self.encoding, self.errors, atomic=self.atomic
            )

            if ctx is not None:
                ctx.call_on_close(lf.close_intelligently)

            return t.cast(t.IO[t.Any], lf)

        f, should_close = open_stream(
            value, self.mode, self.encoding, self.errors, atomic=self.atomic
        )

        # If a context is provided, we automatically close the file
        # at the end of the context execution (or flush out).  If a
        # context does not exist, it's the caller's responsibility to
        # properly close the file.  This for instance happens when the
        # type is used with prompts.
        if ctx is not None:
            if should_close:
                ctx.call_on_close(safecall(f.close))
            else:
                ctx.call_on_close(safecall(f.flush))

        return f
    except OSError as e:
        self.fail(f"'{format_filename(value)}': {e.strerror}", param, ctx)

@property
def command_path(self) -> str:
    """The computed command path.  This is used for the ``usage``
    information on the help page.  It's automatically created by
    combining the info names of the chain of contexts to the root.
    """
    rv = ""
    if self.info_name is not None:
        rv = self.info_name
    if self.parent is not None:
        parent_command_path = [self.parent.command_path]

        if isinstance(self.parent.command, Command):
            for param in self.parent.command.get_params(self):
                parent_command_path.extend(param.get_usage_pieces(self))

        rv = f"{' '.join(parent_command_path)} {rv}"
    return rv.lstrip()

def resolve_lazy_flag(self, value: "t.Union[str, os.PathLike[str]]") -> bool:
    if self.lazy is not None:
        return self.lazy
    if os.fspath(value) == "-":
        return False
    elif "w" in self.mode:
        return True
    return False

def open_url(url: str, wait: bool = False, locate: bool = False) -> int:
    import subprocess

    def _unquote_file(url: str) -> str:
        from urllib.parse import unquote

        if url.startswith("file://"):
            url = unquote(url[7:])

        return url

    if sys.platform == "darwin":
        args = ["open"]
        if wait:
            args.append("-W")
        if locate:
            args.append("-R")
        args.append(_unquote_file(url))
        null = open("/dev/null", "w")
        try:
            return subprocess.Popen(args, stderr=null).wait()
        finally:
            null.close()
    elif WIN:
        if locate:
            url = _unquote_file(url)
            args = ["explorer", f"/select,{url}"]
        else:
            args = ["start"]
            if wait:
                args.append("/WAIT")
            args.append("")
            args.append(url)
        try:
            return subprocess.call(args)
        except OSError:
            # Command not found
            return 127
    elif CYGWIN:
        if locate:
            url = _unquote_file(url)
            args = ["cygstart", os.path.dirname(url)]
        else:
            args = ["cygstart"]
            if wait:
                args.append("-w")
            args.append(url)
        try:
            return subprocess.call(args)
        except OSError:
            # Command not found
            return 127

    try:
        if locate:
            url = os.path.dirname(_unquote_file(url)) or "."
        else:
            url = _unquote_file(url)
        c = subprocess.Popen(["xdg-open", url])
        if wait:
            return c.wait()
        return 0
    except OSError:
        if url.startswith(("http://", "https://")) and not locate and not wait:
            import webbrowser

            webbrowser.open(url)
            return 0
        return 1

def open_stream(
    filename: "t.Union[str, os.PathLike[str]]",
    mode: str = "r",
    encoding: t.Optional[str] = None,
    errors: t.Optional[str] = "strict",
    atomic: bool = False,
) -> t.Tuple[t.IO[t.Any], bool]:
    binary = "b" in mode
    filename = os.fspath(filename)

    # Standard streams first. These are simple because they ignore the
    # atomic flag. Use fsdecode to handle Path("-").
    if os.fsdecode(filename) == "-":
        if any(m in mode for m in ["w", "a", "x"]):
            if binary:
                return get_binary_stdout(), False
            return get_text_stdout(encoding=encoding, errors=errors), False
        if binary:
            return get_binary_stdin(), False
        return get_text_stdin(encoding=encoding, errors=errors), False

    # Non-atomic writes directly go out through the regular open functions.
    if not atomic:
        return _wrap_io_open(filename, mode, encoding, errors), True

    # Some usability stuff for atomic writes
    if "a" in mode:
        raise ValueError(
            "Appending to an existing file is not supported, because that"
            " would involve an expensive `copy`-operation to a temporary"
            " file. Open the file in normal `w`-mode and copy explicitly"
            " if that's what you're after."
        )
    if "x" in mode:
        raise ValueError("Use the `overwrite`-parameter instead.")
    if "w" not in mode:
        raise ValueError("Atomic writes only make sense with `w`-mode.")

    # Atomic writes are more complicated.  They work by opening a file
    # as a proxy in the same folder and then using the fdopen
    # functionality to wrap it in a Python file.  Then we wrap it in an
    # atomic file that moves the file over on close.
    import errno
    import random

    try:
        perm: t.Optional[int] = os.stat(filename).st_mode
    except OSError:
        perm = None

    flags = os.O_RDWR | os.O_CREAT | os.O_EXCL

    if binary:
        flags |= getattr(os, "O_BINARY", 0)

    while True:
        tmp_filename = os.path.join(
            os.path.dirname(filename),
            f".__atomic-write{random.randrange(1 << 32):08x}",
        )
        try:
            fd = os.open(tmp_filename, flags, 0o666 if perm is None else perm)
            break
        except OSError as e:
            if e.errno == errno.EEXIST or (
                os.name == "nt"
                and e.errno == errno.EACCES
                and os.path.isdir(e.filename)
                and os.access(e.filename, os.W_OK)
            ):
                continue
            raise

    if perm is not None:
        os.chmod(tmp_filename, perm)  # in case perm includes bits in umask

    f = _wrap_io_open(fd, mode, encoding, errors)
    af = _AtomicFile(f, tmp_filename, os.path.realpath(filename))
    return t.cast(t.IO[t.Any], af), True

def consume_value(
    self, ctx: Context, opts: t.Mapping[str, "Parameter"]
) -> t.Tuple[t.Any, ParameterSource]:
    value, source = super().consume_value(ctx, opts)

    # The parser will emit a sentinel value if the option can be
    # given as a flag without a value. This is different from None
    # to distinguish from the flag not being given at all.
    if value is _flag_needs_value:
        if self.prompt is not None and not ctx.resilient_parsing:
            value = self.prompt_for_value(ctx)
            source = ParameterSource.PROMPT
        else:
            value = self.flag_value
            source = ParameterSource.COMMANDLINE

    elif (
        self.multiple
        and value is not None
        and any(v is _flag_needs_value for v in value)
    ):
        value = [self.flag_value if v is _flag_needs_value else v for v in value]
        source = ParameterSource.COMMANDLINE

    # The value wasn't set, or used the param's default, prompt if
    # prompting is enabled.
    elif (
        source in {None, ParameterSource.DEFAULT}
        and self.prompt is not None
        and (self.required or self.prompt_required)
        and not ctx.resilient_parsing
    ):
        value = self.prompt_for_value(ctx)
        source = ParameterSource.PROMPT

    return value, source

def _check_multicommand(
    base_command: "MultiCommand", cmd_name: str, cmd: "Command", register: bool = False
) -> None:
    if not base_command.chain or not isinstance(cmd, MultiCommand):
        return
    if register:
        hint = (
            "It is not possible to add multi commands as children to"
            " another multi command that is in chain mode."
        )
    else:
        hint = (
            "Found a multi command as subcommand to a multi command"
            " that is in chain mode. This is not supported."
        )
    raise RuntimeError(
        f"{hint}. Command {base_command.name!r} is set to chain and"
        f" {cmd_name!r} was added as a subcommand but it in itself is a"
        f" multi command. ({cmd_name!r} is a {type(cmd).__name__}"
        f" within a chained {type(base_command).__name__} named"
        f" {base_command.name!r})."
    )

