  Object.keys(headers).forEach(name => {
    const lowerName = name.toLowerCase()
    const generatedHeader = lowerName === 'content-type' || lowerName === 'content-length'
    if (generatedHeader) return
    this.set(name, headers[name])
  })

  // force text/plain
  this.type = 'text'

  let statusCode = err.status || err.statusCode

  // default to 500
  if (typeof statusCode !== 'number' || !statuses.message[statusCode]) statusCode = 500

  // respond
  const code = statuses.message[statusCode]
  const msg = err.expose ? err.message : code
  this.status = err.status = statusCode
  this.length = Buffer.byteLength(msg)
  res.end(msg)
},

handleRequest (ctx, fnMiddleware) {
  const res = ctx.res
  res.statusCode = 404
  const onerror = (err) => ctx.onerror(err)
  const handleResponse = () => respond(ctx)
  onFinished(res, onerror)
  return fnMiddleware(ctx).then(handleResponse).catch(onerror)
}

set body (val) {
  const original = this._body
  this._body = val

  const cleanupPreviousStream = () => {
    if (original && isStream(original)) {
      original.once('error', () => {})
      // Only destroy if the new value is not a stream
      if (!isStream(val)) {
        destroy(original)
      }
    }
  }

  // no content

  if (val == null) {
    if (!statuses.empty[this.status]) {
      if (this.type === 'application/json') {
        this._body = 'null'
        return
      }
      this.status = 204
    }
    if (val === null) this._explicitNullBody = true
    this.remove('Content-Type')
    this.remove('Content-Length')
    this.remove('Transfer-Encoding')
    cleanupPreviousStream()
    return
  }

  // set the status
  if (!this._explicitStatus) this.status = 200

  // set the content-type only if not yet set
  const setType = !this.has('Content-Type')

  // string
  if (typeof val === 'string') {
    if (setType) this.type = /^\s*</.test(val) ? 'html' : 'text'
    this.length = Buffer.byteLength(val)
    cleanupPreviousStream()
    return
  }

  // buffer
  if (Buffer.isBuffer(val)) {
    if (setType) this.type = 'bin'
    this.length = val.length
    cleanupPreviousStream()
    return
  }

  // stream
  if (isStream(val)) {
    onFinish(this.res, destroy.bind(null, val))
    if (original !== val) {
      if (original != null) this.remove('Content-Length')
      cleanupPreviousStream()
    }

    if (setType) this.type = 'bin'
    return
  }

  // ReadableStream
  if (val instanceof ReadableStream) {
    if (setType) this.type = 'bin'
    cleanupPreviousStream()
    return
  }

  // blob
  if (val instanceof Blob) {
    if (setType) this.type = val.type || 'bin'
    this.length = val.size
    cleanupPreviousStream()
    return
  }

  // Response
  if (val instanceof Response) {
    this.status = val.status
    if (setType) this.type = 'bin'
    const headers = val.headers
    for (const key of headers.keys()) {
      this.set(key, headers.get(key))
    }
    cleanupPreviousStream()
    return
  }

  // json
  this.remove('Content-Length')
  if (!this.type || !/\bjson\b/i.test(this.type)) this.type = 'json'
  cleanupPreviousStream()
},

function respond (ctx) {
  // allow bypassing koa
  if (ctx.respond === false) return

  const res = ctx.res

  if (!ctx.writable) return res.end()

  let body = ctx.body
  const code = ctx.status

  // ignore body
  if (statuses.empty[code]) {
    // strip headers
    ctx.body = null
    return res.end()
  }

  if (ctx.method === 'HEAD') {
    if (!res.headersSent && !ctx.response.has('Content-Length')) {
      const { length } = ctx.response
      if (Number.isInteger(length)) ctx.length = length
    }
    return res.end()
  }

  // status body
  if (body === null || body === undefined) {
    if (ctx.response._explicitNullBody) {
      ctx.response.remove('Content-Type')
      ctx.response.remove('Transfer-Encoding')
      ctx.length = 0
      return res.end()
    }
    if (ctx.req.httpVersionMajor >= 2) {
      body = String(code)
    } else {
      body = ctx.message || String(code)
    }
    if (!res.headersSent) {
      ctx.type = 'text'
      ctx.length = Buffer.byteLength(body)
    }
    return res.end(body)
  }

  // responses

  if (Buffer.isBuffer(body)) return res.end(body)
  if (typeof body === 'string') return res.end(body)

  let stream = null
  if (body instanceof Blob) stream = Stream.Readable.from(body.stream())
  else if (body instanceof ReadableStream) stream = Stream.Readable.from(body)
  else if (body instanceof Response) stream = Stream.Readable.from(body?.body || '')
  else if (isStream(body)) stream = body

  if (stream) {
    return Stream.pipeline(stream, res, err => {
      if (err && ctx.app.listenerCount('error')) ctx.onerror(err)
    })
  }

  // body: json
  body = JSON.stringify(body)
  if (!res.headersSent) {
    ctx.length = Buffer.byteLength(body)
  }
  res.end(body)
}

const cleanupPreviousStream = () => {
  if (original && isStream(original)) {
    original.once('error', () => {})
    // Only destroy if the new value is not a stream
    if (!isStream(val)) {
      destroy(original)
    }
  }
}

onerror (err) {
  // don't do anything if there is no error.
  // this allows you to pass `this.onerror`
  // to node-style callbacks.
  if (err == null) return

  // When dealing with cross-globals a normal `instanceof` check doesn't work properly.
  // See https://github.com/koajs/koa/issues/1466
  // We can probably remove it once jest fixes https://github.com/facebook/jest/issues/2549.
  const isNativeError =
    Object.prototype.toString.call(err) === '[object Error]' ||
    err instanceof Error
  if (!isNativeError) err = new Error(util.format('non-error thrown: %j', err))

  let headerSent = false
  if (this.headerSent || !this.writable) {
    headerSent = err.headerSent = true
  }

  // delegate
  this.app.emit('error', err, this)

  // nothing we can do here other
  // than delegate to the app-level
  // handler and log.
  if (headerSent) {
    return
  }

  const { res } = this

  // first unset all headers
  /* istanbul ignore else */
  if (typeof res.getHeaderNames === 'function') {
    res.getHeaderNames().forEach(name => res.removeHeader(name))
  } else {
    res._headers = {} // Node < 7.7
  }

  // then set those specified
  const headers = err.headers || {}
  Object.keys(headers).forEach(name => {
    const lowerName = name.toLowerCase()
    const generatedHeader = lowerName === 'content-type' || lowerName === 'content-length'
    if (generatedHeader) return
    this.set(name, headers[name])
  })

  // force text/plain
  this.type = 'text'

  let statusCode = err.status || err.statusCode

  // default to 500
  if (typeof statusCode !== 'number' || !statuses.message[statusCode]) statusCode = 500

  // respond
  const code = statuses.message[statusCode]
  const msg = err.expose ? err.message : code
  this.status = err.status = statusCode
  this.length = Buffer.byteLength(msg)
  res.end(msg)
},

