def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    align = self.align
    width = console.measure(self.renderable, options=options).maximum
    rendered = console.render(
        Constrain(
            self.renderable, width if self.width is None else min(width, self.width)
        ),
        options.update(height=None),
    )
    lines = list(Segment.split_lines(rendered))
    width, height = Segment.get_shape(lines)
    lines = Segment.set_shape(lines, width, height)
    new_line = Segment.line()
    excess_space = options.max_width - width
    style = console.get_style(self.style) if self.style is not None else None

    def generate_segments() -> Iterable[Segment]:
        if excess_space <= 0:
            # Exact fit
            for line in lines:
                yield from line
                yield new_line

        elif align == "left":
            # Pad on the right
            pad = Segment(" " * excess_space, style) if self.pad else None
            for line in lines:
                yield from line
                if pad:
                    yield pad
                yield new_line

        elif align == "center":
            # Pad left and right
            left = excess_space // 2
            pad = Segment(" " * left, style)
            pad_right = (
                Segment(" " * (excess_space - left), style) if self.pad else None
            )
            for line in lines:
                if left:
                    yield pad
                yield from line
                if pad_right:
                    yield pad_right
                yield new_line

        elif align == "right":
            # Padding on left
            pad = Segment(" " * excess_space, style)
            for line in lines:
                yield pad
                yield from line
                yield new_line

    blank_line = (
        Segment(f"{' ' * (self.width or options.max_width)}\n", style)
        if self.pad
        else Segment("\n")
    )

    def blank_lines(count: int) -> Iterable[Segment]:
        if count > 0:
            for _ in range(count):
                yield blank_line

    vertical_height = self.height or options.height
    iter_segments: Iterable[Segment]
    if self.vertical and vertical_height is not None:
        if self.vertical == "top":
            bottom_space = vertical_height - height
            iter_segments = chain(generate_segments(), blank_lines(bottom_space))
        elif self.vertical == "middle":
            top_space = (vertical_height - height) // 2
            bottom_space = vertical_height - top_space - height
            iter_segments = chain(
                blank_lines(top_space),
                generate_segments(),
                blank_lines(bottom_space),
            )
        else:  #  self.vertical == "bottom":
            top_space = vertical_height - height
            iter_segments = chain(blank_lines(top_space), generate_segments())
    else:
        iter_segments = generate_segments()
    if self.style:
        style = console.get_style(self.style)
        iter_segments = Segment.apply_style(iter_segments, style)
    yield from iter_segments

def generate_segments() -> Iterable[Segment]:
    if excess_space <= 0:
        # Exact fit
        for line in lines:
            yield from line
            yield new_line

    elif align == "left":
        # Pad on the right
        pad = Segment(" " * excess_space, style) if self.pad else None
        for line in lines:
            yield from line
            if pad:
                yield pad
            yield new_line

    elif align == "center":
        # Pad left and right
        left = excess_space // 2
        pad = Segment(" " * left, style)
        pad_right = (
            Segment(" " * (excess_space - left), style) if self.pad else None
        )
        for line in lines:
            if left:
                yield pad
            yield from line
            if pad_right:
                yield pad_right
            yield new_line

    elif align == "right":
        # Padding on left
        pad = Segment(" " * excess_space, style)
        for line in lines:
            yield pad
            yield from line
            yield new_line

def cell_len(text: str, _cell_len: Callable[[str], int] = cached_cell_len) -> int:
    """Get the number of cells required to display text.

    Args:
        text (str): Text to display.

    Returns:
        int: Get the number of cells required to display text.
    """
    if len(text) < 512:
        return _cell_len(text)
    if _is_single_cell_widths(text):
        return len(text)
    return sum(map(get_character_cell_size, text))

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    _padding = Padding.unpack(self.padding)
    renderable = (
        Padding(self.renderable, _padding) if any(_padding) else self.renderable
    )
    style = console.get_style(self.style)
    partial_border_style = console.get_style(self.border_style)
    border_style = style + partial_border_style
    width = (
        options.max_width
        if self.width is None
        else min(options.max_width, self.width)
    )

    safe_box: bool = console.safe_box if self.safe_box is None else self.safe_box
    box = self.box.substitute(options, safe=safe_box)

    def align_text(
        text: Text, width: int, align: str, character: str, style: Style
    ) -> Text:
        """Gets new aligned text.

        Args:
            text (Text): Title or subtitle text.
            width (int): Desired width.
            align (str): Alignment.
            character (str): Character for alignment.
            style (Style): Border style

        Returns:
            Text: New text instance
        """
        text = text.copy()
        text.truncate(width)
        excess_space = width - cell_len(text.plain)
        if text.style:
            text.stylize(console.get_style(text.style))

        if excess_space:
            if align == "left":
                return Text.assemble(
                    text,
                    (character * excess_space, style),
                    no_wrap=True,
                    end="",
                )
            elif align == "center":
                left = excess_space // 2
                return Text.assemble(
                    (character * left, style),
                    text,
                    (character * (excess_space - left), style),
                    no_wrap=True,
                    end="",
                )
            else:
                return Text.assemble(
                    (character * excess_space, style),
                    text,
                    no_wrap=True,
                    end="",
                )
        return text

    title_text = self._title
    if title_text is not None:
        title_text.stylize_before(partial_border_style)

    child_width = (
        width - 2
        if self.expand
        else console.measure(
            renderable, options=options.update_width(width - 2)
        ).maximum
    )
    child_height = self.height or options.height or None
    if child_height:
        child_height -= 2
    if title_text is not None:
        child_width = min(
            options.max_width - 2, max(child_width, title_text.cell_len + 2)
        )

    width = child_width + 2
    child_options = options.update(
        width=child_width, height=child_height, highlight=self.highlight
    )
    lines = console.render_lines(renderable, child_options, style=style)

    line_start = Segment(box.mid_left, border_style)
    line_end = Segment(f"{box.mid_right}", border_style)
    new_line = Segment.line()
    if title_text is None or width <= 4:
        yield Segment(box.get_top([width - 2]), border_style)
    else:
        title_text = align_text(
            title_text,
            width - 4,
            self.title_align,
            box.top,
            border_style,
        )
        yield Segment(box.top_left + box.top, border_style)
        yield from console.render(title_text, child_options.update_width(width - 4))
        yield Segment(box.top + box.top_right, border_style)

    yield new_line
    for line in lines:
        yield line_start
        yield from line
        yield line_end
        yield new_line

    subtitle_text = self._subtitle
    if subtitle_text is not None:
        subtitle_text.stylize_before(partial_border_style)

    if subtitle_text is None or width <= 4:
        yield Segment(box.get_bottom([width - 2]), border_style)
    else:
        subtitle_text = align_text(
            subtitle_text,
            width - 4,
            self.subtitle_align,
            box.bottom,
            border_style,
        )
        yield Segment(box.bottom_left + box.bottom, border_style)
        yield from console.render(
            subtitle_text, child_options.update_width(width - 4)
        )
        yield Segment(box.bottom + box.bottom_right, border_style)

    yield new_line

@lru_cache(4096)
def cached_cell_len(text: str) -> int:
    """Get the number of cells required to display text.

    This method always caches, which may use up a lot of memory. It is recommended to use
    `cell_len` over this method.

    Args:
        text (str): Text to display.

    Returns:
        int: Get the number of cells required to display text.
    """
    if _is_single_cell_widths(text):
        return len(text)
    return sum(map(get_character_cell_size, text))

def render(
    self, renderable: RenderableType, options: Optional[ConsoleOptions] = None
) -> Iterable[Segment]:
    """Render an object in to an iterable of `Segment` instances.

    This method contains the logic for rendering objects with the console protocol.
    You are unlikely to need to use it directly, unless you are extending the library.

    Args:
        renderable (RenderableType): An object supporting the console protocol, or
            an object that may be converted to a string.
        options (ConsoleOptions, optional): An options object, or None to use self.options. Defaults to None.

    Returns:
        Iterable[Segment]: An iterable of segments that may be rendered.
    """

    _options = options or self.options
    if _options.max_width < 1:
        # No space to render anything. This prevents potential recursion errors.
        return
    render_iterable: RenderResult

    renderable = rich_cast(renderable)
    if hasattr(renderable, "__rich_console__") and not isclass(renderable):
        render_iterable = renderable.__rich_console__(self, _options)
    elif isinstance(renderable, str):
        text_renderable = self.render_str(
            renderable, highlight=_options.highlight, markup=_options.markup
        )
        render_iterable = text_renderable.__rich_console__(self, _options)
    else:
        raise errors.NotRenderableError(
            f"Unable to render {renderable!r}; "
            "A str, Segment or object with __rich_console__ method is required"
        )

    try:
        iter_render = iter(render_iterable)
    except TypeError:
        raise errors.NotRenderableError(
            f"object {render_iterable!r} is not renderable"
        )
    _Segment = Segment
    _options = _options.reset_height()
    for render_output in iter_render:
        if isinstance(render_output, _Segment):
            yield render_output
        else:
            yield from self.render(render_output, _options)

